class Journal:
    """One configured SQLite connection and its durable audit API."""

    def __init__(
        self,
        path: Path,
        connection: sqlite3.Connection,
        migration_directory: Path | None = None,
    ) -> None:
        self.path = path
        self._connection = connection
        self._migration_directory = migration_directory
        self._transaction_active = False
        self._transaction_dirty = False
        self._projection_write_allowed = False
        self._report_claim_write_allowed = False
        self._provider_monitoring_write_allowed = False
        self._phase2_adherence_write_allowed = False
        self._source_generation = 0
        self._phase1_publication_read_cache: (
            dict[str, Phase1PublicationSource] | None
        ) = None
        self._phase1_fingerprint_read_cache: (
            _Phase1FingerprintReadCache | None
        ) = None
        self._phase1_exit_market_read_cache: (
            dict[tuple[object, ...], Phase1ExitReviewMarketSource] | None
        ) = None
        self._phase1_canonical_replay_read_cache: (
            dict[tuple[object, ...], Phase1CanonicalReplaySource] | None
        ) = None
        self._phase1_exit_material_read_cache: (
            dict[tuple[object, ...], object] | None
        ) = None
        self._historical_replay_date_contexts: dict[
            int, tuple[ReferenceType[object], object, object]
        ] = {}
        self.__phase1_observation_ingest_token = object()
        self._closed = False

    @classmethod
    def open(
        cls, path: Path, *, migration_directory: Path | None = None
    ) -> Self:
        if cls is not Journal:
            raise JournalError("Journal subclasses cannot issue source authority")
        if not isinstance(path, Path):
            raise InvalidJournalValue("journal path must be a pathlib.Path")
        if migration_directory is not None:
            if not isinstance(migration_directory, Path):
                raise InvalidJournalValue(
                    "migration directory must be a pathlib.Path"
                )
            if not migration_directory.is_dir():
                raise MigrationCorruption("migration directory is unavailable")
        parent = path.parent
        try:
            parent.mkdir(mode=0o700, parents=True, exist_ok=True)
        except OSError as error:
            raise JournalError("journal state directory could not be created") from error
        if not parent.is_dir():
            raise JournalError("journal state parent is not a directory")

        try:
            connection = sqlite3.connect(
                path,
                timeout=BUSY_TIMEOUT_MILLISECONDS / 1_000,
                isolation_level=None,
            )
        except sqlite3.Error as error:
            raise JournalError("journal database could not be opened") from error

        journal = cls(path, connection, migration_directory)
        try:
            journal._verify_database_ownership_snapshot(connection)
            journal._configure_connection()
            journal.migrate()
        except BaseException:
            connection.close()
            journal._closed = True
            raise
        return journal

    def __enter__(self) -> Self:
        self._ensure_open()
        return self

    def __exit__(self, exc_type: object, exc: object, traceback: object) -> None:
        self.close()

    def close(self) -> None:
        if self._closed:
            return
        if self._transaction_active:
            raise JournalError("journal cannot close during an active transaction")
        self._connection.close()
        self._closed = True

    def migrate(self) -> None:
        self._ensure_open()
        migrations = _load_migrations(self._migration_directory)
        expected_schema_sha256s = _derive_expected_schema_sha256s(migrations)
        with self._immediate_connection() as connection:
            self._verify_database_ownership(connection)
            applied = self._read_applied_migrations(connection)
            _verify_applied_migrations(applied, migrations)
            current_version = _pragma_int(connection, "user_version")
            if current_version != len(applied):
                raise MigrationCorruption("database migration version is inconsistent")
            for index, row in enumerate(applied):
                if row[3] != expected_schema_sha256s[index]:
                    raise MigrationDrift(
                        "applied schema differs from packaged migrations"
                    )
            if applied and expected_schema_sha256s[len(applied) - 1] != _schema_sha256(
                connection
            ):
                raise MigrationDrift("database schema differs from packaged migrations")

            recorded = list(applied)
            for migration in migrations[len(applied) :]:
                _require_migration_bookkeeping(connection, tuple(recorded))
                _execute_migration(connection, migration.sql)
                _require_migration_bookkeeping(connection, tuple(recorded))
                _verify_migration_connection_state(connection)
                schema_sha256 = _schema_sha256(connection)
                expected_schema_sha256 = expected_schema_sha256s[
                    migration.version - 1
                ]
                if schema_sha256 != expected_schema_sha256:
                    raise MigrationDrift(
                        "database schema differs from packaged migrations"
                    )
                try:
                    applied_at = _canonical_timestamp(datetime.now(timezone.utc))
                    _sql(connection,
                        "INSERT INTO schema_migrations("
                        "version, name, sha256, schema_sha256, applied_at"
                        ") VALUES (?, ?, ?, ?, ?)",
                        (
                            migration.version,
                            migration.name,
                            migration.sha256,
                            expected_schema_sha256,
                            applied_at,
                        ),
                    )
                    _sql(connection, f"PRAGMA user_version = {migration.version}")
                except sqlite3.Error as error:
                    if _is_busy_error(error):
                        raise JournalBusy("journal is busy") from error
                    raise MigrationCorruption(
                        "migration metadata could not be recorded"
                    ) from error
                recorded.append(
                    (
                        migration.version,
                        migration.name,
                        migration.sha256,
                        expected_schema_sha256,
                        applied_at,
                    )
                )
                _require_migration_bookkeeping(connection, tuple(recorded))

            _require_migration_bookkeeping(connection, tuple(recorded))
            _verify_migration_connection_state(connection)

            if _pragma_int(connection, "application_id") == 0:
                _sql(connection, f"PRAGMA application_id = {APPLICATION_ID}")
            if _pragma_int(connection, "application_id") != APPLICATION_ID:
                raise MigrationCorruption("database application identifier is inconsistent")
            if _sql(connection, "PRAGMA foreign_key_check").fetchone() is not None:
                raise MigrationCorruption("database foreign keys are inconsistent")
            quick_check = _sql(connection, "PRAGMA quick_check").fetchone()
            if quick_check is None or quick_check[0] != "ok":
                raise MigrationCorruption("database integrity check failed")

    @contextmanager
    def transaction(self) -> Iterator[JournalTransaction]:
        self._ensure_open()
        with self._immediate_connection():
            transaction = JournalTransaction(self)
            try:
                yield transaction
            finally:
                transaction._deactivate()

    @contextmanager
    def _phase1_publication_read_scope(self) -> Iterator[None]:
        """Reuse immutable parsing/fingerprints within one nested read only."""
        self._ensure_open()
        created = self._phase1_publication_read_cache is None
        if created:
            self._phase1_publication_read_cache = {}
            self._phase1_fingerprint_read_cache = {}
            self._phase1_exit_market_read_cache = {}
            self._phase1_canonical_replay_read_cache = {}
            self._phase1_exit_material_read_cache = {}
        try:
            yield
        finally:
            if created:
                self._phase1_publication_read_cache = None
                self._phase1_fingerprint_read_cache = None
                self._phase1_exit_market_read_cache = None
                self._phase1_canonical_replay_read_cache = None
                self._phase1_exit_material_read_cache = None

    def append_raw_message(
        self, message_id: str, message_time: datetime, text: str
    ) -> tuple[int, bool]:
        with self.transaction() as transaction:
            return transaction.append_raw_message(message_id, message_time, text)

    def append_execution_event(
        self,
        *,
        raw_message_id: int,
        action_ordinal: int,
        parsed_action: str,
        event_time: datetime,
        signal_id: str | None = None,
        symbol: str | None = None,
        shares: int | None = None,
        price_micros: int | None = None,
        bid_micros: int | None = None,
        ask_micros: int | None = None,
        recommended_stop_micros: int | None = None,
        user_confirmed_stop_micros: int | None = None,
        compliance_result: str = "UNASSESSED",
        reconciliation_state: str = "PENDING",
        details: Mapping[str, object] | None = None,
    ) -> tuple[int, bool]:
        """Append one parsed action outside a larger caller-owned transaction."""
        with self.transaction() as transaction:
            return transaction.append_execution_event(
                raw_message_id=raw_message_id,
                action_ordinal=action_ordinal,
                parsed_action=parsed_action,
                event_time=event_time,
                signal_id=signal_id,
                symbol=symbol,
                shares=shares,
                price_micros=price_micros,
                bid_micros=bid_micros,
                ask_micros=ask_micros,
                recommended_stop_micros=recommended_stop_micros,
                user_confirmed_stop_micros=user_confirmed_stop_micros,
                compliance_result=compliance_result,
                reconciliation_state=reconciliation_state,
                details=details,
            )

    def append_source_observation(
        self,
        *,
        payload: bytes,
        source_uri: str,
        source_type: str,
        provider: str,
        feed: str | None,
        source_time: datetime,
        retrieved_at: datetime,
        provider_sequence: int | None,
        delay_seconds: int | None,
        health_result: str,
        details: Mapping[str, object] | None = None,
    ) -> tuple[int, bool]:
        """Append one content-addressed source observation."""
        with self.transaction() as transaction:
            return transaction.append_source_observation(
                payload=payload,
                source_uri=source_uri,
                source_type=source_type,
                provider=provider,
                feed=feed,
                source_time=source_time,
                retrieved_at=retrieved_at,
                provider_sequence=provider_sequence,
                delay_seconds=delay_seconds,
                health_result=health_result,
                details=details,
            )

    def append_source_observation_receipt(
        self,
        *,
        payload: bytes,
        source_uri: str,
        source_type: str,
        provider: str,
        feed: str | None,
        source_time: datetime,
        retrieved_at: datetime,
        provider_sequence: int | None,
        delay_seconds: int | None,
        health_result: str,
        details: Mapping[str, object] | None = None,
    ) -> SourceObservationReceipt:
        """Append and re-read one exact payload-bearing source receipt."""
        with self.transaction() as transaction:
            row_id, _duplicate = transaction.append_source_observation(
                payload=payload,
                source_uri=source_uri,
                source_type=source_type,
                provider=provider,
                feed=feed,
                source_time=source_time,
                retrieved_at=retrieved_at,
                provider_sequence=provider_sequence,
                delay_seconds=delay_seconds,
                health_result=health_result,
                details=details,
            )
        return self.read_source_observation_receipt(row_id)

    def read_source_observation_receipt(
        self,
        source_observation_id: int,
    ) -> SourceObservationReceipt:
        """Read one exact source observation and its retained payload."""
        source_observation_id = _require_integer(
            source_observation_id,
            "source observation row ID",
            minimum=1,
        )
        return self.read_source_observation_receipts(
            (source_observation_id,)
        )[0]

    def read_source_observation_receipts(
        self,
        source_observation_ids: Sequence[int],
    ) -> tuple[SourceObservationReceipt, ...]:
        """Read a unique receipt sequence without changing caller order."""
        self._ensure_open()
        if self._transaction_active:
            raise JournalError(
                "source observation receipts require a post-commit read"
            )
        if isinstance(
            source_observation_ids,
            (str, bytes, bytearray),
        ) or not isinstance(source_observation_ids, Sequence):
            raise InvalidJournalValue(
                "source observation row IDs must be an exact sequence"
            )
        try:
            row_ids = tuple(
                _require_integer(
                    row_id,
                    "source observation row ID",
                    minimum=1,
                )
                for row_id in source_observation_ids
            )
        except (MemoryError, RuntimeError):
            raise
        except Exception as error:
            if isinstance(error, InvalidJournalValue):
                raise
            raise InvalidJournalValue(
                "source observation row IDs are malformed"
            ) from error
        if len(row_ids) != len(set(row_ids)):
            raise InvalidJournalValue(
                "source observation row IDs must be unique"
            )
        if not row_ids:
            return ()

        receipts = tuple(
            self._read_source_observation_receipt(
                source_observation_id=row_id,
            )
            for row_id in row_ids
        )
        if tuple(receipt.row_id for receipt in receipts) != row_ids:
            raise MigrationCorruption(
                "source observation receipt order is inconsistent"
            )
        for receipt in receipts:
            _remember_journal_source_authority(
                _SOURCE_OBSERVATION_RECEIPT_AUTHORITIES,
                receipt,
                self,
            )
        candidates = tuple(
            _source_observation_receipt_authority_candidate(receipt)
            for receipt in receipts
        )
        if any(candidate is None for candidate in candidates) or (
            _current_journal_source_authority_owner(
                tuple(
                    candidate
                    for candidate in candidates
                    if candidate is not None
                )
            )
            is not self
        ):
            with _JOURNAL_SOURCE_LOCK:
                for receipt in receipts:
                    issued = _SOURCE_OBSERVATION_RECEIPT_AUTHORITIES.get(
                        id(receipt)
                    )
                    if issued is not None and issued[0]() is receipt:
                        _SOURCE_OBSERVATION_RECEIPT_AUTHORITIES.pop(
                            id(receipt),
                            None,
                        )
            raise JournalError(
                "source observation receipt changed during readback"
            )
        return receipts

    def owns_source_observation_receipt(self, source: object) -> bool:
        """Return whether this Journal owns the exact current receipt object."""
        candidate = _source_observation_receipt_authority_candidate(source)
        return candidate is not None and (
            _current_journal_source_authority_owner((candidate,)) is self
        )

    def _actual_close_receipt_binding_material(
        self,
        binding: ActualCloseReceiptBinding,
        *,
        review_at: datetime,
        mark_cutoff: datetime,
        query_cutoff: datetime,
    ) -> dict[str, object]:
        if type(binding) is not ActualCloseReceiptBinding:
            raise InvalidJournalValue(
                "actual close receipt bindings must be exact binding values"
            )
        role = _actual_close_role(binding.source_role)
        symbol = _actual_close_scope(binding.symbol, role)
        receipt = binding.receipt
        candidate = _source_observation_receipt_authority_candidate(receipt)
        if candidate is None or (
            _current_journal_source_authority_owner((candidate,)) is not self
        ):
            raise InvalidJournalValue(
                "actual close receipt is not current for this Journal"
            )
        if (
            receipt.health_result != "OK"
            or receipt.retrieved_at < review_at
            or receipt.retrieved_at > query_cutoff
            or receipt.source_time > query_cutoff
            or (
                role not in _ACTUAL_CLOSE_MARKET_ROLE_TYPES
                and receipt.source_time > review_at
            )
        ):
            raise InvalidJournalValue(
                "actual close receipt chronology or health is invalid"
            )
        source_row, payload_row = self._phase1_core_source_rows(
            source_observation_id=receipt.row_id,
        )
        if (
            receipt.row_reference
            != _journal_row_reference(
                "source_observations",
                _SOURCE_OBSERVATION_COLUMNS,
                source_row,
            )
            or receipt.payload_row_reference
            != _journal_row_reference(
                "phase1_source_payloads",
                _PHASE1_SOURCE_PAYLOAD_COLUMNS,
                payload_row,
            )
            or bytes(payload_row[3]) != receipt.source_payload
        ):
            raise InvalidJournalValue(
                "actual close receipt conflicts with durable source rows"
            )
        details = _canonical_stored_details(
            receipt.details_json,
            label="actual close source receipt",
        )
        if role in _ACTUAL_CLOSE_MARKET_ROLE_TYPES:
            expected_type = _ACTUAL_CLOSE_MARKET_ROLE_TYPES[role]
            if receipt.source_type != expected_type:
                raise InvalidJournalValue(
                    "actual close market role conflicts with source type"
                )
            collection, _collection_is_list = (
                _validate_phase1_alpaca_page_contract(
                    source_row,
                    receipt.source_payload,
                )
            )
            metadata = _phase1_recompute_alpaca_page_metadata(
                payload=receipt.source_payload,
                request_url=receipt.source_uri,
                source_type=receipt.source_type,
                retrieved_at=receipt.retrieved_at,
            )
            if (
                details
                != {
                    "source_observation_id": (
                        metadata.source_observation_id
                    )
                }
                or receipt.source_time != metadata.source_time
                or receipt.delay_seconds != metadata.delay_seconds
                or receipt.provider_sequence is not None
                or (role != "IEX_FRESHNESS" and receipt.source_time > mark_cutoff)
                or (role == "IEX_FRESHNESS" and receipt.source_time > review_at)
            ):
                raise InvalidJournalValue(
                    "actual close market receipt metadata is inconsistent"
                )
            parsed = urlsplit(receipt.source_uri)
            query: dict[str, list[str]] = {}
            for name, value in parse_qsl(
                parsed.query,
                keep_blank_values=True,
            ):
                query.setdefault(name, []).append(value)
            expected_feed = "iex" if role == "IEX_FRESHNESS" else "sip"
            expected_timeframe = {
                "SIP_MINUTE_BAR": "1Min",
                "SIP_DAILY_BAR": "1Day",
            }.get(role)
            try:
                document = json.loads(receipt.source_payload.decode("utf-8"))
            except (UnicodeDecodeError, json.JSONDecodeError) as error:
                raise InvalidJournalValue(
                    "actual close market receipt payload is invalid"
                ) from error
            if (
                query.get("symbols") != [symbol]
                or query.get("feed") != [expected_feed]
                or (
                    expected_timeframe is not None
                    and query.get("timeframe") != [expected_timeframe]
                )
                or set(document[collection]) != {symbol}
            ):
                raise InvalidJournalValue(
                    "actual close market receipt scope is inconsistent"
                )
        elif role == "EVENT_EVIDENCE":
            expected_detail_keys = {
                "accession",
                "issuer_cik",
                "source_observation_id",
                "source_role",
                "symbol",
                "timestamp_source",
            }
            if set(details) != expected_detail_keys or details["symbol"] != symbol:
                raise InvalidJournalValue(
                    "actual close event evidence details are inconsistent"
                )
            source_type = receipt.source_type
            issuer_cik = details["issuer_cik"]
            accession = details["accession"]
            source_role = details["source_role"]
            if source_type == "SEC_SUBMISSIONS":
                valid = (
                    type(issuer_cik) is str
                    and re.fullmatch(r"[0-9]{10}", issuer_cik) is not None
                    and accession is None
                    and source_role is None
                    and receipt.provider
                    == "U.S. Securities and Exchange Commission"
                    and receipt.feed == "SEC_SUBMISSIONS_METADATA"
                    and receipt.source_uri
                    == f"https://data.sec.gov/submissions/CIK{issuer_cik}.json"
                )
            elif source_type == "SEC_ARCHIVE":
                parsed_archive = urlsplit(receipt.source_uri)
                try:
                    archive_port = parsed_archive.port
                except ValueError:
                    archive_port = -1
                archive_path_matches = False
                if (
                    type(issuer_cik) is str
                    and re.fullmatch(r"[0-9]{10}", issuer_cik) is not None
                    and type(accession) is str
                    and re.fullmatch(
                        r"[0-9]{10}-[0-9]{2}-[0-9]{6}",
                        accession,
                    )
                    is not None
                ):
                    archive_path_matches = re.fullmatch(
                        rf"/Archives/edgar/data/{int(issuer_cik)}/"
                        rf"{accession.replace('-', '')}/"
                        r"[A-Za-z0-9][A-Za-z0-9._-]*",
                        parsed_archive.path,
                    ) is not None
                valid = (
                    type(issuer_cik) is str
                    and re.fullmatch(r"[0-9]{10}", issuer_cik) is not None
                    and type(accession) is str
                    and re.fullmatch(
                        r"[0-9]{10}-[0-9]{2}-[0-9]{6}",
                        accession,
                    )
                    is not None
                    and source_role is None
                    and receipt.provider
                    == "U.S. Securities and Exchange Commission"
                    and receipt.feed == "SEC_FILING_METADATA"
                    and parsed_archive.scheme == "https"
                    and parsed_archive.hostname == "www.sec.gov"
                    and parsed_archive.netloc
                    in {"www.sec.gov", "www.sec.gov:443"}
                    and archive_port in (None, 443)
                    and parsed_archive.username is None
                    and parsed_archive.password is None
                    and not parsed_archive.query
                    and not parsed_archive.fragment
                    and archive_path_matches
                )
            elif source_type == "OFFICIAL_REFERENCE":
                from . import evidence as evidence_module

                authority = evidence_module._SCOPED_REFERENCE_AUTHORITIES.get(
                    source_role
                )
                valid = (
                    source_role
                    in {
                        f"ISSUER_IR:{symbol}",
                        f"CORPORATE_ACTION:{symbol}",
                    }
                    and receipt.feed == "PRIMARY_METADATA"
                    and authority is not None
                    and authority[0] == issuer_cik
                    and (receipt.source_uri, receipt.provider) in authority[1]
                    and accession is None
                )
            else:
                valid = False
            if not valid:
                raise InvalidJournalValue(
                    "actual close event evidence source identity is invalid"
                )
        else:
            expected_url, expected_provider = (
                _ACTUAL_CLOSE_GLOBAL_REFERENCE_URLS[role]
            )
            if (
                receipt.source_type != "OFFICIAL_REFERENCE"
                or receipt.source_uri != expected_url
                or receipt.provider != expected_provider
                or receipt.feed
                not in (
                    {"PRIMARY_METADATA", "UNAVAILABLE"}
                    if role == "OPERATIONAL_STATUS"
                    else {"PRIMARY_METADATA"}
                )
                or details.get("source_role") != role
                or details.get("symbol") is not None
                or set(details)
                != {
                    "accession",
                    "issuer_cik",
                    "source_observation_id",
                    "source_role",
                    "symbol",
                    "timestamp_source",
                }
            ):
                raise InvalidJournalValue(
                    "actual close official reference identity is invalid"
                )
        if not _is_current_journal_source_authority_without_callbacks(receipt):
            raise InvalidJournalValue(
                "actual close receipt changed during validation"
            )
        return {
            "failure_code": None,
            "received_at": _canonical_timestamp(receipt.retrieved_at),
            "receipt": receipt,
            "receipt_source_digest": receipt.source_digest,
            "source_observation_id": receipt.row_id,
            "source_role": role,
            "symbol": symbol,
        }

    def _actual_close_failure_binding_material(
        self,
        binding: ActualCloseFailureBinding,
        *,
        session_date: date,
        review_at: datetime,
        query_cutoff: datetime,
    ) -> dict[str, object]:
        if type(binding) is not ActualCloseFailureBinding:
            raise InvalidJournalValue(
                "actual close failure bindings must be exact binding values"
            )
        role = _actual_close_role(binding.source_role)
        symbol = _actual_close_scope(binding.symbol, role)
        failure_code = _actual_close_failure_code(binding.failure_code)
        received_at = _parse_canonical_timestamp(
            _canonical_timestamp(binding.received_at)
        )
        if (
            received_at < review_at
            or received_at > query_cutoff
            or received_at.astimezone(ZoneInfo("America/New_York")).date()
            != session_date
        ):
            raise InvalidJournalValue(
                "actual close failure chronology is invalid"
            )
        return {
            "failure_code": failure_code,
            "received_at": _canonical_timestamp(received_at),
            "receipt": None,
            "receipt_source_digest": None,
            "source_observation_id": None,
            "source_role": role,
            "symbol": symbol,
        }

    @staticmethod
    def _actual_close_alpaca_page_chain(
        materials: Sequence[Mapping[str, object]],
    ) -> tuple[Mapping[str, object], ...]:
        """Return one exact provider-token page chain in request order."""
        if not materials:
            raise InvalidJournalValue(
                "actual close market page chain is empty"
            )
        first_receipt = materials[0]["receipt"]
        symbol = materials[0]["symbol"]
        if (
            type(first_receipt) is not SourceObservationReceipt
            or type(symbol) is not str
        ):
            raise InvalidJournalValue(
                "actual close market page chain is malformed"
            )
        source_type = first_receipt.source_type
        collection = _PHASE1_ALPACA_SOURCE_CONTRACTS[source_type][0]
        pages_by_request_token: dict[
            str | None,
            tuple[Mapping[str, object], object],
        ] = {}
        request_digests: set[str] = set()
        request_urls: list[str] = []
        for material in materials:
            receipt = material["receipt"]
            if (
                type(receipt) is not SourceObservationReceipt
                or receipt.source_type != source_type
                or material["symbol"] != symbol
            ):
                raise InvalidJournalValue(
                    "actual close market pages disagree on role or scope"
                )
            parsed = urlsplit(receipt.source_uri)
            try:
                pairs = parse_qsl(
                    parsed.query,
                    keep_blank_values=True,
                    strict_parsing=True,
                )
                document = json.loads(receipt.source_payload.decode("utf-8"))
            except (
                UnicodeDecodeError,
                json.JSONDecodeError,
                ValueError,
            ) as error:
                raise InvalidJournalValue(
                    "actual close market pagination is malformed"
                ) from error
            query: dict[str, list[str]] = {}
            for name, value in pairs:
                query.setdefault(name, []).append(value)
            token_values = query.get("page_token", [])
            if (
                len(token_values) > 1
                or (token_values and not token_values[0])
            ):
                raise InvalidJournalValue(
                    "actual close market request token is malformed"
                )
            request_token = token_values[0] if token_values else None
            if request_token in pages_by_request_token:
                raise InvalidJournalValue(
                    "actual close market request token is duplicated"
                )
            if (
                type(document) is not dict
                or "next_page_token" not in document
                and source_type != "ALPACA_LATEST_QUOTES"
            ):
                raise InvalidJournalValue(
                    "actual close market response token is missing"
                )
            next_token = document.get("next_page_token")
            if next_token is not None and (
                type(next_token) is not str
                or not next_token
                or len(next_token) > 512
                or not next_token.isascii()
                or not next_token.isprintable()
            ):
                raise InvalidJournalValue(
                    "actual close market response token is malformed"
                )
            pages_by_request_token[request_token] = (material, next_token)
            request_digests.add(
                _phase1_provider_request_digest(
                    collection=collection,
                    requested_symbols=(symbol,),
                    request_url=receipt.source_uri,
                )
            )
            request_urls.append(receipt.source_uri)
        if len(request_digests) != 1:
            raise InvalidJournalValue(
                "actual close market pages disagree on their base request"
            )
        if source_type == "ALPACA_LATEST_QUOTES":
            page = pages_by_request_token.get(None)
            if (
                len(pages_by_request_token) != 1
                or page is None
                or page[1] is not None
            ):
                raise InvalidJournalValue(
                    "actual close latest quote must be one terminal page"
                )
            return (page[0],)
        _phase1_historical_request_window(tuple(request_urls))
        ordered: list[Mapping[str, object]] = []
        request_token: str | None = None
        prior_retrieved_at: datetime | None = None
        while True:
            page = pages_by_request_token.pop(request_token, None)
            if page is None:
                raise InvalidJournalValue(
                    "actual close market page chain is disconnected"
                )
            material, next_token = page
            receipt = material["receipt"]
            assert type(receipt) is SourceObservationReceipt
            if (
                prior_retrieved_at is not None
                and receipt.retrieved_at < prior_retrieved_at
            ):
                raise InvalidJournalValue(
                    "actual close market page retrieval order regresses"
                )
            ordered.append(material)
            prior_retrieved_at = receipt.retrieved_at
            if next_token is None:
                break
            request_token = str(next_token)
        if pages_by_request_token:
            raise InvalidJournalValue(
                "actual close market page chain has extra or terminal pages"
            )
        return tuple(ordered)

    def _actual_close_validate_and_order_materials(
        self,
        materials: Sequence[Mapping[str, object]],
    ) -> list[Mapping[str, object]]:
        """Require one complete role result per scope and canonicalize it."""
        grouped: dict[
            tuple[str | None, str],
            list[Mapping[str, object]],
        ] = {}
        symbols: set[str] = set()
        for material in materials:
            symbol = material["symbol"]
            role = str(material["source_role"])
            if type(symbol) is str:
                symbols.add(symbol)
            grouped.setdefault((symbol, role), []).append(material)
        expected_scopes = {
            *((None, role) for role in _ACTUAL_CLOSE_GLOBAL_ROLES),
            *(
                (symbol, role)
                for symbol in symbols
                for role in _ACTUAL_CLOSE_SYMBOL_ROLES
            ),
        }
        if set(grouped) != expected_scopes:
            raise InvalidJournalValue(
                "actual close review source roles are incomplete"
            )
        ordered: list[Mapping[str, object]] = []
        for scope in sorted(
            grouped,
            key=lambda value: (
                _ACTUAL_CLOSE_SOURCE_ROLES.index(value[1]),
                "" if value[0] is None else value[0],
            ),
        ):
            group = grouped[scope]
            receipt_materials = [
                material
                for material in group
                if material["receipt"] is not None
            ]
            failure_materials = [
                material
                for material in group
                if material["failure_code"] is not None
            ]
            if bool(receipt_materials) == bool(failure_materials) or (
                failure_materials and len(failure_materials) != 1
            ):
                raise InvalidJournalValue(
                    "actual close scoped role must contain receipt pages XOR failure"
                )
            if failure_materials:
                ordered.extend(failure_materials)
            elif scope[1] in _ACTUAL_CLOSE_MARKET_ROLE_TYPES:
                ordered.extend(
                    self._actual_close_alpaca_page_chain(receipt_materials)
                )
            else:
                ordered.extend(
                    sorted(
                        receipt_materials,
                        key=lambda material: (
                            material["receipt"].source_uri,
                            material["receipt"].observation_sha256,
                        ),
                    )
                )
        return ordered

    @staticmethod
    def _actual_close_review_identity_material(
        *,
        session_date: str,
        review_at: str,
        mark_cutoff: str,
        query_cutoff: str,
        retrieved_at: str,
        bindings: Sequence[Mapping[str, object]],
    ) -> dict[str, object]:
        return {
            "bindings": [
                {
                    "binding_ordinal": ordinal,
                    "failure_code": binding["failure_code"],
                    "received_at": binding["received_at"],
                    "receipt_source_digest": binding["receipt_source_digest"],
                    "source_observation_id": binding["source_observation_id"],
                    "source_role": binding["source_role"],
                    "symbol": binding["symbol"],
                }
                for ordinal, binding in enumerate(bindings, start=1)
            ],
            "mark_cutoff": mark_cutoff,
            "query_cutoff": query_cutoff,
            "retrieved_at": retrieved_at,
            "review_at": review_at,
            "session_date": session_date,
        }

    def append_actual_close_review(
        self,
        *,
        session_date: date,
        review_at: datetime,
        mark_cutoff: datetime,
        query_cutoff: datetime,
        retrieved_at: datetime,
        receipt_bindings: Sequence[ActualCloseReceiptBinding],
        failure_bindings: Sequence[ActualCloseFailureBinding],
    ) -> ActualCloseReviewSource:
        """Append a deterministic receipt/failure manifest and reread it."""
        self._ensure_open()
        if self._transaction_active:
            raise JournalError(
                "actual close reviews require an outermost transaction"
            )
        if type(receipt_bindings) is not tuple or type(failure_bindings) is not tuple:
            raise InvalidJournalValue(
                "actual close bindings must be exact tuples"
            )
        session_text = _canonical_date(session_date)
        normalized_review = _parse_canonical_timestamp(
            _canonical_timestamp(review_at)
        )
        normalized_mark = _parse_canonical_timestamp(
            _canonical_timestamp(mark_cutoff)
        )
        normalized_query = _parse_canonical_timestamp(
            _canonical_timestamp(query_cutoff)
        )
        normalized_retrieved = _parse_canonical_timestamp(
            _canonical_timestamp(retrieved_at)
        )
        if not (
            normalized_mark < normalized_review
            <= normalized_query
            <= normalized_retrieved
        ) or any(
            value.date() != session_date
            or value.astimezone(ZoneInfo("America/New_York")).date()
            != session_date
            for value in (
                normalized_mark,
                normalized_review,
                normalized_query,
                normalized_retrieved,
            )
        ):
            raise InvalidJournalValue(
                "actual close review chronology is invalid"
            )
        materials = [
            self._actual_close_receipt_binding_material(
                binding,
                review_at=normalized_review,
                mark_cutoff=normalized_mark,
                query_cutoff=normalized_query,
            )
            for binding in receipt_bindings
        ]
        materials.extend(
            self._actual_close_failure_binding_material(
                binding,
                session_date=session_date,
                review_at=normalized_review,
                query_cutoff=normalized_query,
            )
            for binding in failure_bindings
        )
        if len(
            {
                material["source_observation_id"]
                for material in materials
                if material["source_observation_id"] is not None
            }
        ) != len(receipt_bindings):
            raise InvalidJournalValue(
                "actual close receipt bindings must be unique"
            )
        failure_scopes = [
            (material["symbol"], material["source_role"])
            for material in materials
            if material["failure_code"] is not None
        ]
        if len(failure_scopes) != len(set(failure_scopes)):
            raise InvalidJournalValue(
                "actual close failure roles must be unique per scope"
            )
        receipt_scopes = {
            (material["symbol"], material["source_role"])
            for material in materials
            if material["source_observation_id"] is not None
        }
        if receipt_scopes.intersection(failure_scopes):
            raise InvalidJournalValue(
                "actual close scoped role must contain receipts XOR failure"
            )
        materials = self._actual_close_validate_and_order_materials(materials)
        timing = {
            "mark_cutoff": _canonical_timestamp(normalized_mark),
            "query_cutoff": _canonical_timestamp(normalized_query),
            "retrieved_at": _canonical_timestamp(normalized_retrieved),
            "review_at": _canonical_timestamp(normalized_review),
            "session_date": session_text,
        }
        identity_material = self._actual_close_review_identity_material(
            **timing,
            bindings=materials,
        )
        review_id = _actual_close_semantic_digest(
            "stock-monitor/actual-close-review-id/v1",
            identity_material,
        )
        source_digest = _actual_close_semantic_digest(
            "stock-monitor/actual-close-review-source/v1",
            {"review_id": review_id, **identity_material},
        )
        review_material = {
            "expected_binding_count": len(materials),
            "mark_cutoff": timing["mark_cutoff"],
            "query_cutoff": timing["query_cutoff"],
            "retrieved_at": timing["retrieved_at"],
            "review_at": timing["review_at"],
            "review_id": review_id,
            "session_date": session_text,
            "source_digest": source_digest,
        }
        record_sha256 = hashlib.sha256(
            _canonical_audit_json(review_material).encode("utf-8")
        ).hexdigest()
        binding_values: list[tuple[object, ...]] = []
        for ordinal, material in enumerate(materials, start=1):
            record_material = {
                "binding_ordinal": ordinal,
                "failure_code": material["failure_code"],
                "received_at": material["received_at"],
                "review_id": review_id,
                "source_observation_id": material["source_observation_id"],
                "source_role": material["source_role"],
                "symbol": material["symbol"],
            }
            binding_values.append(
                (
                    *(
                        record_material[column]
                        for column in _ACTUAL_CLOSE_SOURCE_BINDING_COLUMNS[1:-1]
                    ),
                    hashlib.sha256(
                        _canonical_audit_json(record_material).encode("utf-8")
                    ).hexdigest(),
                )
            )
        with self.transaction():
            candidates = tuple(
                _source_observation_receipt_authority_candidate(
                    material["receipt"]
                )
                for material in materials
                if material["receipt"] is not None
            )
            if any(candidate is None for candidate in candidates) or (
                candidates
                and _current_journal_source_authority_owner(
                    tuple(candidate for candidate in candidates if candidate is not None)
                )
                is not self
            ):
                raise InvalidJournalValue(
                    "actual close receipt set changed before write"
                )
            existing = _sql(
                self._connection,
                "SELECT " + ", ".join(_ACTUAL_CLOSE_REVIEW_COLUMNS)
                + " FROM actual_close_reviews WHERE session_date = ? "
                "AND query_cutoff = ?",
                (session_text, timing["query_cutoff"]),
            ).fetchone()
            if existing is not None:
                existing_bindings = _sql(
                    self._connection,
                    "SELECT " + ", ".join(_ACTUAL_CLOSE_SOURCE_BINDING_COLUMNS)
                    + " FROM actual_close_source_bindings WHERE review_id = ? "
                    "ORDER BY binding_ordinal",
                    (review_id,),
                ).fetchall()
                if tuple(existing[1:]) != (
                    review_id,
                    session_text,
                    timing["review_at"],
                    timing["mark_cutoff"],
                    timing["query_cutoff"],
                    timing["retrieved_at"],
                    len(materials),
                    source_digest,
                    record_sha256,
                ) or tuple(tuple(row[1:]) for row in existing_bindings) != tuple(
                    binding_values
                ):
                    raise IdempotencyConflict(
                        "actual close review conflicts with stored content"
                    )
            else:
                if any(
                    not _is_current_journal_source_authority_without_callbacks(
                        material["receipt"]
                    )
                    for material in materials
                    if material["receipt"] is not None
                ):
                    raise InvalidJournalValue(
                        "actual close receipt changed during write validation"
                    )
                try:
                    with self._provider_monitoring_write():
                        _sql(
                            self._connection,
                            "INSERT INTO actual_close_reviews("
                            + ", ".join(_ACTUAL_CLOSE_REVIEW_COLUMNS[1:])
                            + ") VALUES ("
                            + ", ".join("?" for _ in _ACTUAL_CLOSE_REVIEW_COLUMNS[1:])
                            + ")",
                            tuple(review_material[column] for column in _ACTUAL_CLOSE_REVIEW_COLUMNS[1:-1])
                            + (record_sha256,),
                        )
                        for values in binding_values:
                            _sql(
                                self._connection,
                                "INSERT INTO actual_close_source_bindings("
                                + ", ".join(_ACTUAL_CLOSE_SOURCE_BINDING_COLUMNS[1:])
                                + ") VALUES ("
                                + ", ".join("?" for _ in _ACTUAL_CLOSE_SOURCE_BINDING_COLUMNS[1:])
                                + ")",
                                values,
                            )
                except sqlite3.IntegrityError as error:
                    raise IdempotencyConflict(
                        "actual close review conflicts with stored content"
                    ) from error
        return self.read_actual_close_review_source(
            review_id,
            query_cutoff=normalized_query,
        )

    def read_actual_close_review_source(
        self,
        review_id: str,
        *,
        query_cutoff: datetime,
    ) -> ActualCloseReviewSource:
        """Read and authenticate one complete close-review binding manifest."""
        self._ensure_open()
        if self._transaction_active:
            raise JournalError(
                "actual close review source requires a post-commit read"
            )
        review_id = _require_sha256(review_id, "actual close review ID")
        normalized_cutoff = _parse_canonical_timestamp(
            _canonical_timestamp(query_cutoff)
        )
        row = _sql(
            self._connection,
            "SELECT " + ", ".join(_ACTUAL_CLOSE_REVIEW_COLUMNS)
            + " FROM actual_close_reviews WHERE review_id = ? COLLATE BINARY",
            (review_id,),
        ).fetchone()
        if row is None:
            raise InvalidJournalValue("actual close review does not exist")
        stored = dict(zip(_ACTUAL_CLOSE_REVIEW_COLUMNS, tuple(row), strict=True))
        stored_cutoff = _parse_canonical_timestamp(str(stored["query_cutoff"]))
        if stored_cutoff != normalized_cutoff:
            raise InvalidJournalValue(
                "actual close review query cutoff is not exact"
            )
        binding_rows = _sql(
            self._connection,
            "SELECT " + ", ".join(_ACTUAL_CLOSE_SOURCE_BINDING_COLUMNS)
            + " FROM actual_close_source_bindings WHERE review_id = ? "
            "ORDER BY binding_ordinal, id",
            (review_id,),
        ).fetchall()
        expected_count = int(stored["expected_binding_count"])
        if len(binding_rows) != expected_count or tuple(
            int(binding_row[2]) for binding_row in binding_rows
        ) != tuple(range(1, expected_count + 1)):
            raise MigrationCorruption(
                "actual close review binding manifest is incomplete"
            )
        receipt_ids = tuple(
            int(binding_row[5])
            for binding_row in binding_rows
            if binding_row[5] is not None
        )
        receipts = self.read_source_observation_receipts(receipt_ids)
        receipts_by_id = {receipt.row_id: receipt for receipt in receipts}
        normalized_review = _parse_canonical_timestamp(str(stored["review_at"]))
        normalized_mark = _parse_canonical_timestamp(str(stored["mark_cutoff"]))
        normalized_retrieved = _parse_canonical_timestamp(
            str(stored["retrieved_at"])
        )
        material_rows: list[dict[str, object]] = []
        binding_sources: list[ActualCloseReviewBindingSource] = []
        for binding_row in binding_rows:
            binding_stored = dict(
                zip(
                    _ACTUAL_CLOSE_SOURCE_BINDING_COLUMNS,
                    tuple(binding_row),
                    strict=True,
                )
            )
            receipt = (
                None
                if binding_stored["source_observation_id"] is None
                else receipts_by_id.get(int(binding_stored["source_observation_id"]))
            )
            input_binding: ActualCloseReceiptBinding | ActualCloseFailureBinding
            if receipt is not None:
                input_binding = ActualCloseReceiptBinding(
                    None if binding_stored["symbol"] is None else str(binding_stored["symbol"]),
                    str(binding_stored["source_role"]),
                    receipt,
                )
                material = self._actual_close_receipt_binding_material(
                    input_binding,
                    review_at=normalized_review,
                    mark_cutoff=normalized_mark,
                    query_cutoff=stored_cutoff,
                )
            elif binding_stored["failure_code"] is not None:
                input_binding = ActualCloseFailureBinding(
                    None if binding_stored["symbol"] is None else str(binding_stored["symbol"]),
                    str(binding_stored["source_role"]),
                    str(binding_stored["failure_code"]),
                    _parse_canonical_timestamp(str(binding_stored["received_at"])),
                )
                material = self._actual_close_failure_binding_material(
                    input_binding,
                    session_date=date.fromisoformat(str(stored["session_date"])),
                    review_at=normalized_review,
                    query_cutoff=stored_cutoff,
                )
            else:
                raise MigrationCorruption(
                    "actual close review binding is neither receipt nor failure"
                )
            record_material = {
                column: binding_stored[column]
                for column in _ACTUAL_CLOSE_SOURCE_BINDING_COLUMNS[1:-1]
            }
            if (
                int(binding_stored["binding_ordinal"])
                != len(material_rows) + 1
                or str(binding_stored["received_at"]) != material["received_at"]
                or binding_stored["source_observation_id"]
                != material["source_observation_id"]
                or binding_stored["failure_code"] != material["failure_code"]
                or str(binding_stored["record_sha256"])
                != hashlib.sha256(
                    _canonical_audit_json(record_material).encode("utf-8")
                ).hexdigest()
            ):
                raise MigrationCorruption(
                    "actual close review binding integrity failed"
                )
            material_rows.append(material)
            binding_sources.append(
                ActualCloseReviewBindingSource(
                    row_id=int(binding_stored["id"]),
                    review_id=review_id,
                    binding_ordinal=int(binding_stored["binding_ordinal"]),
                    symbol=material["symbol"],
                    source_role=str(material["source_role"]),
                    source_observation_id=material["source_observation_id"],
                    failure_code=material["failure_code"],
                    received_at=_parse_canonical_timestamp(str(material["received_at"])),
                    record_sha256=str(binding_stored["record_sha256"]),
                    receipt=receipt,
                    row_reference=_journal_row_reference(
                        "actual_close_source_bindings",
                        _ACTUAL_CLOSE_SOURCE_BINDING_COLUMNS,
                        binding_row,
                    ),
                )
            )
        try:
            canonical_material_rows = (
                self._actual_close_validate_and_order_materials(material_rows)
            )
        except InvalidJournalValue as error:
            raise MigrationCorruption(
                "actual close review binding cohort is invalid"
            ) from error
        if material_rows != canonical_material_rows:
            raise MigrationCorruption(
                "actual close review binding order is not deterministic"
            )
        identity_material = self._actual_close_review_identity_material(
            session_date=str(stored["session_date"]),
            review_at=str(stored["review_at"]),
            mark_cutoff=str(stored["mark_cutoff"]),
            query_cutoff=str(stored["query_cutoff"]),
            retrieved_at=str(stored["retrieved_at"]),
            bindings=material_rows,
        )
        expected_review_id = _actual_close_semantic_digest(
            "stock-monitor/actual-close-review-id/v1",
            identity_material,
        )
        expected_source_digest = _actual_close_semantic_digest(
            "stock-monitor/actual-close-review-source/v1",
            {"review_id": expected_review_id, **identity_material},
        )
        review_material = {
            column: stored[column]
            for column in _ACTUAL_CLOSE_REVIEW_COLUMNS[1:-1]
        }
        expected_record = hashlib.sha256(
            _canonical_audit_json(review_material).encode("utf-8")
        ).hexdigest()
        if (
            review_id != expected_review_id
            or str(stored["source_digest"]) != expected_source_digest
            or str(stored["record_sha256"]) != expected_record
        ):
            raise MigrationCorruption(
                "actual close review identity or integrity failed"
            )
        review_reference = _journal_row_reference(
            "actual_close_reviews",
            _ACTUAL_CLOSE_REVIEW_COLUMNS,
            row,
        )
        references = (
            review_reference,
            *(binding.row_reference for binding in binding_sources),
            *(reference for receipt in receipts for reference in (
                receipt.row_reference,
                receipt.payload_row_reference,
            )),
        )
        references = tuple(
            sorted(
                {(reference.table, reference.row_id): reference for reference in references}.values(),
                key=lambda reference: (reference.table, reference.row_id),
            )
        )
        source = ActualCloseReviewSource(
            row_id=int(stored["id"]),
            review_id=review_id,
            session_date=date.fromisoformat(str(stored["session_date"])),
            review_at=normalized_review,
            mark_cutoff=normalized_mark,
            query_cutoff=stored_cutoff,
            retrieved_at=normalized_retrieved,
            expected_binding_count=expected_count,
            bindings=tuple(binding_sources),
            receipts=receipts,
            source_digest=expected_source_digest,
            record_sha256=expected_record,
            row_reference=review_reference,
            row_references=references,
        )
        source_identity, source_authority = (
            _phase1_reader_source_registration_material(
                _ACTUAL_CLOSE_REVIEW_SOURCE_AUTHORITIES,
                source,
                self,
            )
        )
        with _JOURNAL_SOURCE_LOCK:
            _ACTUAL_CLOSE_REVIEW_SOURCE_AUTHORITIES[source_identity] = (
                source_authority
            )
        if not (
            is_verified_actual_close_review_source(source)
            and _is_current_phase1_source_authority_without_callbacks(source)
        ):
            with _JOURNAL_SOURCE_LOCK:
                if _ACTUAL_CLOSE_REVIEW_SOURCE_AUTHORITIES.get(source_identity) is source_authority:
                    _ACTUAL_CLOSE_REVIEW_SOURCE_AUTHORITIES.pop(source_identity, None)
            raise JournalError(
                "actual close review source changed during readback"
            )
        return source

    def owns_actual_close_review_source(self, source: object) -> bool:
        candidate = _phase1_source_authority_candidate(source)
        return type(source) is ActualCloseReviewSource and candidate is not None and (
            _current_journal_source_authority_owner((candidate,)) is self
        )

    def is_current_actual_close_review_source(self, source: object) -> bool:
        return self.owns_actual_close_review_source(source)

    def _close_recommendation_plan_identity(
        self,
        *,
        symbol: str,
        position_plan_digest: str,
        query_cutoff: datetime,
    ) -> tuple[ActualPositionPlanBindingSource, Phase1SignalSource]:
        rows = _sql(
            self._connection,
            "SELECT " + ", ".join(_ACTUAL_POSITION_PLAN_BINDING_COLUMNS)
            + " FROM actual_position_plan_bindings "
            "WHERE symbol = ? COLLATE BINARY "
            "AND binding_kind = 'LIVE_CONFIRM_ANCHOR' "
            "AND recorded_at <= ? ORDER BY id",
            (symbol, _canonical_timestamp(query_cutoff)),
        ).fetchall()
        matches: list[ActualPositionPlanBindingSource] = []
        for row in rows:
            binding = self._actual_position_plan_binding_source_from_row(row)
            digest = hashlib.sha256(
                _canonical_audit_json(
                    {
                        "namespace": (
                            "stock-monitor/actual-position-plan-identity/v1"
                        ),
                        "opening_actual_lifecycle_id": (
                            binding.position_lifecycle_id
                        ),
                        "opening_actual_event_id": (
                            binding.confirmation_event_id
                        ),
                        "primary_plan_digest": binding.primary_plan_digest,
                        "symbol": symbol,
                    }
                ).encode("utf-8")
            ).hexdigest()
            if digest == position_plan_digest:
                matches.append(binding)
        if len(matches) != 1:
            raise MigrationCorruption(
                "close recommendation plan identity is missing or ambiguous"
            )
        anchor = matches[0]
        signal_source = self._read_phase1_signal_source(
            anchor.signal_id,
            query_cutoff=query_cutoff,
        )
        if (
            anchor.binding_ordinal != 1
            or anchor.symbol != symbol
            or signal_source.role != "PRIMARY"
            or signal_source.symbol != symbol
            or signal_source.primary_plan_digest != anchor.primary_plan_digest
        ):
            raise MigrationCorruption(
                "close recommendation primary plan identity is inconsistent"
            )
        return anchor, signal_source

    @staticmethod
    def _close_recommendation_source_digest(
        *,
        recommendation_id: str,
        review_source_digest: str,
        position_plan_digest: str,
        signal_id: str,
        opening_actual_lifecycle_id: str,
        opening_actual_event_id: str,
        opening_actual_execution_event_id: int,
        initial_stop_micros: int,
        prior_recommended_stop_micros: int | None,
        recommended_stop_micros: int,
        action: str,
        reason_codes: tuple[str, ...],
        received_at: str,
    ) -> str:
        return _actual_close_semantic_digest(
            "stock-monitor/close-recommendation-source/v1",
            {
                "action": action,
                "initial_stop_micros": initial_stop_micros,
                "opening_actual_event_id": opening_actual_event_id,
                "opening_actual_execution_event_id": (
                    opening_actual_execution_event_id
                ),
                "opening_actual_lifecycle_id": opening_actual_lifecycle_id,
                "position_plan_digest": position_plan_digest,
                "prior_recommended_stop_micros": (
                    prior_recommended_stop_micros
                ),
                "reason_codes": list(reason_codes),
                "received_at": received_at,
                "recommendation_id": recommendation_id,
                "recommended_stop_micros": recommended_stop_micros,
                "review_source_digest": review_source_digest,
                "signal_id": signal_id,
            },
        )

    def append_close_recommendation(
        self,
        decision_source: object,
    ) -> CloseRecommendationSource:
        """Persist only one exact issued ACTUAL close decision authority."""
        from .risk import (
            ActualCloseDecisionSource,
            _is_current_actual_close_decision_source_without_callbacks,
            is_issued_actual_close_decision_source,
        )

        self._ensure_open()
        if self._transaction_active:
            raise JournalError(
                "close recommendations require an outermost transaction"
            )
        if type(decision_source) is not ActualCloseDecisionSource or not (
            is_issued_actual_close_decision_source(decision_source)
        ):
            raise InvalidJournalValue(
                "close recommendation requires an issued close decision"
            )
        review_source = decision_source.review_source
        position_plan_source = decision_source.position_plan_source
        latest_source = decision_source.latest_recommendation_source
        replay_recommendation = decision_source.replay_recommendation
        review_candidate = _phase1_source_authority_candidate(review_source)
        plan_candidate = _phase1_source_authority_candidate(
            position_plan_source
        )
        latest_candidate = _phase1_source_authority_candidate(latest_source)
        if (
            type(review_source) is not ActualCloseReviewSource
            or type(position_plan_source) is not ActualPositionPlanSource
            or type(latest_source) is not LatestCloseRecommendationSource
            or review_candidate is None
            or plan_candidate is None
            or latest_candidate is None
            or _current_journal_source_authority_owner(
                (review_candidate, plan_candidate, latest_candidate)
            )
            is not self
        ):
            raise InvalidJournalValue(
                "close recommendation inputs are not exact current sources"
            )
        if (
            review_source.query_cutoff != position_plan_source.query_cutoff
            or latest_source.query_cutoff != position_plan_source.query_cutoff
            or latest_source.position_plan_source is not position_plan_source
            or not any(
                binding.symbol == position_plan_source.symbol
                for binding in review_source.bindings
            )
        ):
            raise InvalidJournalValue(
                "close recommendation review conflicts with position plan"
            )
        stop_micros = _require_integer(
            decision_source.recommended_stop_micros,
            "close recommendation stop",
            minimum=1,
        )
        action = decision_source.action
        if action not in {"HOLD", "EXIT", "TIGHTEN_STOP"}:
            raise InvalidJournalValue(
                "close recommendation action is unsupported"
            )
        reasons = _close_recommendation_reason_codes(
            decision_source.reason_codes
        )
        normalized_received = _parse_canonical_timestamp(
            _canonical_timestamp(decision_source.received_at)
        )
        if (
            normalized_received != review_source.retrieved_at
            or normalized_received > position_plan_source.query_cutoff
            or normalized_received.date() != review_source.session_date
            or normalized_received.astimezone(
                ZoneInfo("America/New_York")
            ).date()
            != review_source.session_date
        ):
            raise InvalidJournalValue(
                "close recommendation receipt chronology is invalid"
            )
        signal_source = position_plan_source.signal_source
        anchor = position_plan_source.plan_bindings[0]
        initial_stop_micros = signal_source.recommended_stop_micros
        if (
            anchor.binding_kind != "LIVE_CONFIRM_ANCHOR"
            or anchor.binding_ordinal != 1
            or anchor.position_lifecycle_id
            != position_plan_source.opening_actual_lifecycle_id
            or anchor.confirmation_event_id
            != position_plan_source.opening_actual_event_id
            or anchor.confirmation_execution_event_id
            != position_plan_source.opening_actual_execution_event_id
        ):
            raise InvalidJournalValue(
                "close recommendation plan anchor is inconsistent"
            )
        if replay_recommendation is not None:
            if latest_source.recommendation is not replay_recommendation:
                raise InvalidJournalValue(
                    "close recommendation replay is not exact"
                )
            prior_stop = replay_recommendation.prior_recommended_stop_micros
        else:
            prior_stop = (
                None
                if latest_source.recommendation is None
                else latest_source.recommendation.recommended_stop_micros
            )
        stop_baseline = max(
            initial_stop_micros,
            initial_stop_micros if prior_stop is None else prior_stop,
        )
        if (
            stop_micros < stop_baseline
            or (action == "HOLD" and stop_micros != stop_baseline)
            or (action == "TIGHTEN_STOP" and stop_micros <= stop_baseline)
        ):
            raise InvalidJournalValue(
                "close recommendation action conflicts with durable stop history"
            )
        received_text = _canonical_timestamp(normalized_received)
        identity_material = {
            "action": action,
            "position_plan_digest": position_plan_source.position_plan_digest,
            "reason_codes": list(reasons),
            "received_at": received_text,
            "recommended_stop_micros": stop_micros,
            "review_id": review_source.review_id,
            "session_date": review_source.session_date.isoformat(),
            "symbol": position_plan_source.symbol,
        }
        recommendation_id = _actual_close_semantic_digest(
            "stock-monitor/close-recommendation-id/v1",
            identity_material,
        )
        source_digest = self._close_recommendation_source_digest(
            recommendation_id=recommendation_id,
            review_source_digest=review_source.source_digest,
            position_plan_digest=position_plan_source.position_plan_digest,
            signal_id=signal_source.signal_id,
            opening_actual_lifecycle_id=(
                position_plan_source.opening_actual_lifecycle_id
            ),
            opening_actual_event_id=position_plan_source.opening_actual_event_id,
            opening_actual_execution_event_id=(
                position_plan_source.opening_actual_execution_event_id
            ),
            initial_stop_micros=initial_stop_micros,
            prior_recommended_stop_micros=prior_stop,
            recommended_stop_micros=stop_micros,
            action=action,
            reason_codes=reasons,
            received_at=received_text,
        )
        reasons_json = _canonical_json(list(reasons))
        record_material = {
            "action": action,
            "position_plan_digest": position_plan_source.position_plan_digest,
            "reasons_json": reasons_json,
            "received_at": received_text,
            "recommendation_id": recommendation_id,
            "recommended_stop_micros": stop_micros,
            "review_id": review_source.review_id,
            "session_date": review_source.session_date.isoformat(),
            "source_digest": source_digest,
            "symbol": position_plan_source.symbol,
        }
        record_sha256 = hashlib.sha256(
            _canonical_audit_json(record_material).encode("utf-8")
        ).hexdigest()
        values = tuple(
            record_sha256 if column == "record_sha256" else record_material[column]
            for column in _CLOSE_RECOMMENDATION_COLUMNS[1:]
        )
        with self.transaction():
            review_candidate = _phase1_source_authority_candidate(review_source)
            plan_candidate = _phase1_source_authority_candidate(
                position_plan_source
            )
            latest_candidate = _phase1_source_authority_candidate(
                latest_source
            )
            if (
                review_candidate is None
                or plan_candidate is None
                or latest_candidate is None
                or _current_journal_source_authority_owner(
                    (review_candidate, plan_candidate, latest_candidate)
                )
                is not self
            ):
                raise InvalidJournalValue(
                    "close recommendation inputs changed before write"
                )
            existing = _sql(
                self._connection,
                "SELECT " + ", ".join(_CLOSE_RECOMMENDATION_COLUMNS)
                + " FROM close_recommendations WHERE session_date = ? "
                "AND symbol = ? COLLATE BINARY "
                "AND position_plan_digest = ? COLLATE BINARY",
                (
                    review_source.session_date.isoformat(),
                    position_plan_source.symbol,
                    position_plan_source.position_plan_digest,
                ),
            ).fetchone()
            # No caller-dispatchable validation remains after this exact
            # decision/root/source seal and before a new append-only insert.
            if not _is_current_actual_close_decision_source_without_callbacks(
                decision_source
            ):
                raise InvalidJournalValue(
                    "close recommendation decision changed during validation"
                )
            if existing is not None:
                if tuple(existing[1:]) != values:
                    raise IdempotencyConflict(
                        "close recommendation conflicts with stored content"
                    )
            else:
                if replay_recommendation is not None:
                    raise InvalidJournalValue(
                        "close recommendation replay has no stored decision"
                    )
                try:
                    with self._provider_monitoring_write():
                        _sql(
                            self._connection,
                            "INSERT INTO close_recommendations("
                            + ", ".join(_CLOSE_RECOMMENDATION_COLUMNS[1:])
                            + ") VALUES ("
                            + ", ".join("?" for _ in _CLOSE_RECOMMENDATION_COLUMNS[1:])
                            + ")",
                            values,
                        )
                except sqlite3.IntegrityError as error:
                    raise IdempotencyConflict(
                        "close recommendation conflicts with stored content"
                    ) from error
            self._clear_sqlite_callbacks_before_authority_commit()
            if not _is_current_actual_close_decision_source_without_callbacks(
                decision_source
            ):
                raise InvalidJournalValue(
                    "close recommendation decision changed during write"
                )
        return self.read_close_recommendation_source(
            recommendation_id,
            query_cutoff=position_plan_source.query_cutoff,
        )

    def read_close_recommendation_source(
        self,
        recommendation_id: str,
        *,
        query_cutoff: datetime,
        position_plan_source: ActualPositionPlanSource | None = None,
    ) -> CloseRecommendationSource:
        """Read one durable recommendation without accepting caller identity."""
        self._ensure_open()
        if self._transaction_active:
            raise JournalError(
                "close recommendation source requires a post-commit read"
            )
        recommendation_id = _require_sha256(
            recommendation_id,
            "close recommendation ID",
        )
        normalized_cutoff = _parse_canonical_timestamp(
            _canonical_timestamp(query_cutoff)
        )
        row = _sql(
            self._connection,
            "SELECT " + ", ".join(_CLOSE_RECOMMENDATION_COLUMNS)
            + " FROM close_recommendations "
            "WHERE recommendation_id = ? COLLATE BINARY",
            (recommendation_id,),
        ).fetchone()
        if row is None:
            raise InvalidJournalValue("close recommendation does not exist")
        stored = dict(zip(_CLOSE_RECOMMENDATION_COLUMNS, tuple(row), strict=True))
        received_at = _parse_canonical_timestamp(str(stored["received_at"]))
        if received_at > normalized_cutoff:
            raise InvalidJournalValue("close recommendation is lookahead")
        review_row = _sql(
            self._connection,
            "SELECT query_cutoff FROM actual_close_reviews "
            "WHERE review_id = ? COLLATE BINARY",
            (str(stored["review_id"]),),
        ).fetchone()
        if review_row is None:
            raise MigrationCorruption(
                "close recommendation review is missing"
            )
        review_source = self.read_actual_close_review_source(
            str(stored["review_id"]),
            query_cutoff=_parse_canonical_timestamp(str(review_row[0])),
        )
        if not (
            received_at == review_source.retrieved_at
            and received_at <= review_source.query_cutoff
        ):
            raise MigrationCorruption(
                "close recommendation receipt is outside its review window"
            )
        symbol = str(stored["symbol"])
        position_plan_digest = str(stored["position_plan_digest"])
        anchor, signal_source = self._close_recommendation_plan_identity(
            symbol=symbol,
            position_plan_digest=position_plan_digest,
            query_cutoff=normalized_cutoff,
        )
        if position_plan_source is not None:
            plan_candidate = _phase1_source_authority_candidate(
                position_plan_source
            )
            if (
                type(position_plan_source) is not ActualPositionPlanSource
                or plan_candidate is None
                or _current_journal_source_authority_owner((plan_candidate,))
                is not self
                or position_plan_source.query_cutoff != normalized_cutoff
                or position_plan_source.symbol != symbol
                or position_plan_source.position_plan_digest
                != position_plan_digest
                or position_plan_source.signal_source.signal_id
                != signal_source.signal_id
            ):
                raise InvalidJournalValue(
                    "close recommendation position plan is not exact"
                )
        try:
            raw_reasons = json.loads(str(stored["reasons_json"]))
        except json.JSONDecodeError as error:
            raise MigrationCorruption(
                "close recommendation reasons are invalid JSON"
            ) from error
        if type(raw_reasons) is not list:
            raise MigrationCorruption(
                "close recommendation reasons are not an array"
            )
        try:
            reasons = _close_recommendation_reason_codes(tuple(raw_reasons))
        except InvalidJournalValue as error:
            raise MigrationCorruption(
                "close recommendation reasons are invalid"
            ) from error
        prior_row = _sql(
            self._connection,
            "SELECT recommended_stop_micros FROM close_recommendations "
            "WHERE symbol = ? COLLATE BINARY "
            "AND position_plan_digest = ? COLLATE BINARY "
            "AND received_at < ? ORDER BY received_at DESC, id DESC LIMIT 1",
            (symbol, position_plan_digest, str(stored["received_at"])),
        ).fetchone()
        prior_stop = None if prior_row is None else int(prior_row[0])
        initial_stop = signal_source.recommended_stop_micros
        stop_micros = int(stored["recommended_stop_micros"])
        stop_baseline = max(
            initial_stop,
            initial_stop if prior_stop is None else prior_stop,
        )
        action = str(stored["action"])
        if (
            stop_micros < stop_baseline
            or (action == "HOLD" and stop_micros != stop_baseline)
            or (action == "TIGHTEN_STOP" and stop_micros <= stop_baseline)
        ):
            raise MigrationCorruption(
                "close recommendation action conflicts with stop history"
            )
        expected_recommendation_id = _actual_close_semantic_digest(
            "stock-monitor/close-recommendation-id/v1",
            {
                "action": action,
                "position_plan_digest": position_plan_digest,
                "reason_codes": list(reasons),
                "received_at": str(stored["received_at"]),
                "recommended_stop_micros": stop_micros,
                "review_id": str(stored["review_id"]),
                "session_date": str(stored["session_date"]),
                "symbol": symbol,
            },
        )
        if recommendation_id != expected_recommendation_id:
            raise MigrationCorruption(
                "close recommendation semantic identity is inconsistent"
            )
        expected_source_digest = self._close_recommendation_source_digest(
            recommendation_id=recommendation_id,
            review_source_digest=review_source.source_digest,
            position_plan_digest=position_plan_digest,
            signal_id=signal_source.signal_id,
            opening_actual_lifecycle_id=anchor.position_lifecycle_id,
            opening_actual_event_id=anchor.confirmation_event_id,
            opening_actual_execution_event_id=(
                anchor.confirmation_execution_event_id
            ),
            initial_stop_micros=initial_stop,
            prior_recommended_stop_micros=prior_stop,
            recommended_stop_micros=stop_micros,
            action=action,
            reason_codes=reasons,
            received_at=str(stored["received_at"]),
        )
        record_material = {
            column: stored[column]
            for column in _CLOSE_RECOMMENDATION_COLUMNS[1:-1]
        }
        expected_record = hashlib.sha256(
            _canonical_audit_json(record_material).encode("utf-8")
        ).hexdigest()
        if (
            str(stored["source_digest"]) != expected_source_digest
            or str(stored["record_sha256"]) != expected_record
            or review_source.session_date.isoformat()
            != str(stored["session_date"])
            or review_source.review_id != str(stored["review_id"])
        ):
            raise MigrationCorruption(
                "close recommendation identity or integrity failed"
            )
        recommendation_reference = _journal_row_reference(
            "close_recommendations",
            _CLOSE_RECOMMENDATION_COLUMNS,
            row,
        )
        references = (
            recommendation_reference,
            *review_source.row_references,
            anchor.row_reference,
            *signal_source.row_references,
        )
        references = tuple(
            sorted(
                {(reference.table, reference.row_id): reference for reference in references}.values(),
                key=lambda reference: (reference.table, reference.row_id),
            )
        )
        source = CloseRecommendationSource(
            row_id=int(stored["id"]),
            recommendation_id=recommendation_id,
            review_id=str(stored["review_id"]),
            session_date=date.fromisoformat(str(stored["session_date"])),
            symbol=symbol,
            position_plan_digest=position_plan_digest,
            signal_id=signal_source.signal_id,
            opening_actual_lifecycle_id=anchor.position_lifecycle_id,
            opening_actual_event_id=anchor.confirmation_event_id,
            opening_actual_execution_event_id=(
                anchor.confirmation_execution_event_id
            ),
            initial_stop_micros=initial_stop,
            prior_recommended_stop_micros=prior_stop,
            recommended_stop_micros=stop_micros,
            action=action,
            reason_codes=reasons,
            received_at=received_at,
            query_cutoff=normalized_cutoff,
            review_source=review_source,
            signal_source=signal_source,
            anchor_binding=anchor,
            source_digest=expected_source_digest,
            record_sha256=expected_record,
            row_reference=recommendation_reference,
            row_references=references,
        )
        source_identity, source_authority = (
            _phase1_reader_source_registration_material(
                _CLOSE_RECOMMENDATION_SOURCE_AUTHORITIES,
                source,
                self,
            )
        )
        with _JOURNAL_SOURCE_LOCK:
            _CLOSE_RECOMMENDATION_SOURCE_AUTHORITIES[source_identity] = (
                source_authority
            )
        if not (
            is_verified_close_recommendation_source(source)
            and _is_current_phase1_source_authority_without_callbacks(source)
            and (
                position_plan_source is None
                or _is_current_phase1_source_authority_without_callbacks(
                    position_plan_source
                )
            )
        ):
            with _JOURNAL_SOURCE_LOCK:
                if _CLOSE_RECOMMENDATION_SOURCE_AUTHORITIES.get(source_identity) is source_authority:
                    _CLOSE_RECOMMENDATION_SOURCE_AUTHORITIES.pop(source_identity, None)
            raise JournalError(
                "close recommendation source changed during readback"
            )
        return source

    def read_latest_close_recommendation_source(
        self,
        *,
        position_plan_source: ActualPositionPlanSource,
        query_cutoff: datetime,
    ) -> LatestCloseRecommendationSource:
        """Issue exact positive-or-negative recommendation history authority."""
        self._ensure_open()
        if self._transaction_active:
            raise JournalError(
                "latest close recommendation requires a post-commit read"
            )
        normalized_cutoff = _parse_canonical_timestamp(
            _canonical_timestamp(query_cutoff)
        )
        plan_candidate = _phase1_source_authority_candidate(
            position_plan_source
        )
        if (
            type(position_plan_source) is not ActualPositionPlanSource
            or plan_candidate is None
            or _current_journal_source_authority_owner((plan_candidate,))
            is not self
            or position_plan_source.query_cutoff != normalized_cutoff
        ):
            raise InvalidJournalValue(
                "latest recommendation requires an exact current position plan"
            )
        rows = _sql(
            self._connection,
            "SELECT " + ", ".join(_CLOSE_RECOMMENDATION_COLUMNS)
            + " FROM close_recommendations WHERE symbol = ? COLLATE BINARY "
            "AND position_plan_digest = ? COLLATE BINARY "
            "AND received_at <= ? ORDER BY received_at, id",
            (
                position_plan_source.symbol,
                position_plan_source.position_plan_digest,
                _canonical_timestamp(normalized_cutoff),
            ),
        ).fetchall()
        recommendation_sources = tuple(
            self.read_close_recommendation_source(
                str(row[1]),
                query_cutoff=normalized_cutoff,
                position_plan_source=position_plan_source,
            )
            for row in rows
        )
        latest = None if not recommendation_sources else recommendation_sources[-1]
        ids = tuple(source.recommendation_id for source in recommendation_sources)
        references = (
            *position_plan_source.row_references,
            *(source.row_reference for source in recommendation_sources),
        )
        references = tuple(
            sorted(
                {(reference.table, reference.row_id): reference for reference in references}.values(),
                key=lambda reference: (reference.table, reference.row_id),
            )
        )
        source_digest = _journal_bundle_digest(
            "stock-monitor/latest-close-recommendation-source/v1",
            references,
            {
                "eligible_recommendation_ids": list(ids),
                "position_plan_digest": position_plan_source.position_plan_digest,
                "query_cutoff": _canonical_timestamp(normalized_cutoff),
                "symbol": position_plan_source.symbol,
            },
        )
        history = LatestCloseRecommendationSource(
            symbol=position_plan_source.symbol,
            position_plan_digest=position_plan_source.position_plan_digest,
            query_cutoff=normalized_cutoff,
            position_plan_source=position_plan_source,
            recommendation=latest,
            eligible_recommendation_ids=ids,
            recommendation_highwater=(
                0 if not recommendation_sources else max(source.row_id for source in recommendation_sources)
            ),
            row_references=references,
            source_digest=source_digest,
        )
        source_identity, source_authority = (
            _phase1_reader_source_registration_material(
                _LATEST_CLOSE_RECOMMENDATION_SOURCE_AUTHORITIES,
                history,
                self,
            )
        )
        with _JOURNAL_SOURCE_LOCK:
            _LATEST_CLOSE_RECOMMENDATION_SOURCE_AUTHORITIES[source_identity] = (
                source_authority
            )
        if not (
            is_verified_latest_close_recommendation_source(history)
            and _is_current_phase1_source_authority_without_callbacks(history)
            and _is_current_phase1_source_authority_without_callbacks(
                position_plan_source
            )
        ):
            with _JOURNAL_SOURCE_LOCK:
                if _LATEST_CLOSE_RECOMMENDATION_SOURCE_AUTHORITIES.get(source_identity) is source_authority:
                    _LATEST_CLOSE_RECOMMENDATION_SOURCE_AUTHORITIES.pop(source_identity, None)
            raise JournalError(
                "latest close recommendation changed during readback"
            )
        return history

    def owns_close_recommendation_source(self, source: object) -> bool:
        candidate = _phase1_source_authority_candidate(source)
        return type(source) is CloseRecommendationSource and candidate is not None and (
            _current_journal_source_authority_owner((candidate,)) is self
        )

    def is_current_close_recommendation_source(self, source: object) -> bool:
        return self.owns_close_recommendation_source(source)

    def owns_latest_close_recommendation_source(self, source: object) -> bool:
        candidate = _phase1_source_authority_candidate(source)
        return type(source) is LatestCloseRecommendationSource and candidate is not None and (
            _current_journal_source_authority_owner((candidate,)) is self
        )

    def is_current_latest_close_recommendation_source(
        self,
        source: object,
    ) -> bool:
        return self.owns_latest_close_recommendation_source(source)

    def start_phase2_window(
        self,
        *,
        promotion_decision: object,
        start_action: object,
        calendar_resolver: object,
    ) -> Phase2WindowSource:
        """Persist one exact PASSED-promotion OPTION_WINDOW_START boundary."""
        from zoneinfo import ZoneInfo

        from .risk import SessionCalendarResolver, _calendar_digest
        from .validation import PromotionDecision, PromotionStatus

        self._ensure_open()
        registered_promotion = _registered_promotion_decision_source(
            promotion_decision
        )
        if (
            registered_promotion is None
            or registered_promotion[1] is not self
            or type(promotion_decision) is not PromotionDecision
        ):
            raise InvalidJournalValue(
                "Phase 2 window promotion identity is unverified"
            )
        historical_promotion_source = registered_promotion[0]
        if (
            type(historical_promotion_source)
            is not Phase1ValidationWindowSource
            or _journal_registered_action_source_owner(start_action) is not self
            or type(start_action) is not JournalActionSource
        ):
            raise InvalidJournalValue(
                "Phase 2 window start action identity is unverified"
            )
        if (
            not isinstance(calendar_resolver, SessionCalendarResolver)
            or not calendar_resolver.release_verified
        ):
            raise InvalidJournalValue("Phase 2 window calendar is unverified")
        calendar_digest = _calendar_digest(calendar_resolver)
        if historical_promotion_source.calendar_digest != calendar_digest:
            raise InvalidJournalValue("Phase 2 window calendar is inconsistent")

        current_promotion = self.read_phase1_promotion_decision(
            historical_promotion_source.validation_window_id,
            through_session=historical_promotion_source.through_session,
            query_cutoff=historical_promotion_source.query_cutoff,
            calendar_resolver=calendar_resolver,
        )
        current_promotion_source = current_promotion._phase1_source
        if (
            type(current_promotion) is not PromotionDecision
            or current_promotion != promotion_decision
            or not current_promotion.passed
            or current_promotion.status is not PromotionStatus.PASSED
            or type(current_promotion_source)
            is not Phase1ValidationWindowSource
            or current_promotion_source.source_digest
            != historical_promotion_source.source_digest
            or current_promotion.authority_digest
            != promotion_decision.authority_digest
        ):
            raise InvalidJournalValue(
                "Phase 2 window promotion cannot be rederived"
            )
        current_action = self._read_action_source(
            execution_event_id=start_action.execution_event_id,
        )
        if current_action != start_action:
            raise InvalidJournalValue(
                "Phase 2 window start action cannot be rederived"
            )
        if current_action.domain_kind != "OPTION_PAPER_WINDOW_START":
            raise InvalidJournalValue(
                "Phase 2 window requires OPTION_PAPER_WINDOW_START"
            )
        started_at = current_action.event_time
        received_at = current_action.received_at
        promotion_cutoff = current_promotion_source.query_cutoff
        if (
            started_at <= promotion_cutoff
            or received_at <= promotion_cutoff
            or started_at > received_at
        ):
            raise InvalidJournalValue(
                "Phase 2 window start must be strictly after promotion"
            )
        started_session = started_at.astimezone(
            ZoneInfo("America/New_York")
        ).date()
        if not calendar_resolver.is_open(started_session):
            raise InvalidJournalValue(
                "Phase 2 window must start on an open session"
            )
        promotion_signal_ids = tuple(
            source.signal_id
            for source in current_promotion_source.signal_sources
        )
        if (
            not promotion_signal_ids
            or len(set(promotion_signal_ids)) != len(promotion_signal_ids)
        ):
            raise InvalidJournalValue(
                "Phase 2 promotion signal cohort is incomplete"
            )
        promotion_signal_ids_json = _canonical_audit_json(
            list(promotion_signal_ids)
        )
        window_id = _phase2_stable_id(
            "stock-monitor/phase2-window/v1",
            current_promotion_source.validation_window_id,
            current_promotion_source.source_digest,
            str(current_promotion.authority_digest),
            current_action.source_digest,
            str(current_action.execution_event_id),
        )
        source_references = _phase2_row_references(
            current_promotion_source.row_references,
            current_action.row_references,
        )
        source_digest = _journal_bundle_digest(
            "stock-monitor/phase2-window-source/v1",
            source_references,
            {
                "window_id": window_id,
                "validation_window_id": (
                    current_promotion_source.validation_window_id
                ),
                "promotion_source_digest": (
                    current_promotion_source.source_digest
                ),
                "promotion_decision_digest": (
                    current_promotion.authority_digest
                ),
                "promotion_signal_ids": list(promotion_signal_ids),
                "promotion_through_session": (
                    current_promotion_source.through_session.isoformat()
                ),
                "promotion_query_cutoff": _canonical_timestamp(
                    promotion_cutoff
                ),
                "start_execution_event_id": (
                    current_action.execution_event_id
                ),
                "start_raw_message_id": current_action.raw_message_id,
                "started_session": started_session.isoformat(),
                "started_at": _canonical_timestamp(started_at),
                "received_at": _canonical_timestamp(received_at),
                "starting_capital_micros": 5_000_000_000,
                "calendar_digest": calendar_digest,
            },
        )
        values_without_hash = (
            window_id,
            current_promotion_source.validation_window_id,
            current_promotion_source.source_digest,
            current_promotion.authority_digest,
            promotion_signal_ids_json,
            current_promotion_source.through_session.isoformat(),
            _canonical_timestamp(promotion_cutoff),
            current_action.execution_event_id,
            current_action.raw_message_id,
            started_session.isoformat(),
            _canonical_timestamp(started_at),
            _canonical_timestamp(received_at),
            5_000_000_000,
            calendar_digest,
            source_digest,
        )
        record_sha256 = _phase2_plain_record_digest(
            _PHASE2_WINDOW_COLUMNS,
            values_without_hash,
        )
        phase2_write_plan = frozenset(
            {
                (
                    "phase2_windows",
                    record_sha256,
                    tuple(values_without_hash),
                )
            }
        )
        with self.transaction() as transaction:
            existing = _sql(
                self._connection,
                "SELECT " + ", ".join(_PHASE2_WINDOW_COLUMNS)
                + " FROM phase2_windows WHERE window_id = ? COLLATE BINARY "
                "OR start_execution_event_id = ?",
                (window_id, current_action.execution_event_id),
            ).fetchone()
            expected_window_row = (*values_without_hash, record_sha256)
            inserted_window = existing is None
            if existing is not None:
                if tuple(existing[1:]) != expected_window_row:
                    raise IdempotencyConflict(
                        "Phase 2 window identity conflicts with stored content"
                    )
            else:
                transaction._mark_dirty()
                try:
                    _sql(
                        self._connection,
                        "INSERT INTO phase2_windows("
                        + ", ".join(_PHASE2_WINDOW_COLUMNS[1:])
                        + ") VALUES ("
                        + ", ".join("?" for _ in expected_window_row)
                        + ")",
                        expected_window_row,
                    )
                except sqlite3.IntegrityError as error:
                    raise IdempotencyConflict(
                        "Phase 2 window identity conflicts with stored content"
                    ) from error
            stored_window = _sql(
                self._connection,
                "SELECT " + ", ".join(_PHASE2_WINDOW_COLUMNS)
                + " FROM phase2_windows WHERE window_id = ? COLLATE BINARY",
                (window_id,),
            ).fetchone()
            if (
                stored_window is None
                or tuple(stored_window[1:]) != expected_window_row
            ):
                raise IdempotencyConflict(
                    "Phase 2 window identity conflicts with stored content"
                )
            window_reference = _journal_row_reference(
                "phase2_windows",
                _PHASE2_WINDOW_COLUMNS,
                stored_window,
            )
            genesis_record = _phase2_window_genesis_record(
                window_reference,
                window_id=window_id,
                window_source_digest=source_digest,
                started_session=started_session,
                started_at=started_at,
                received_at=received_at,
            )
            phase2_write_plan = frozenset(
                {
                    (
                        "phase2_windows",
                        record_sha256,
                        tuple(values_without_hash),
                    ),
                    (
                        "phase2_equity_points",
                        str(genesis_record[-1]),
                        tuple(genesis_record[:-1]),
                    ),
                }
            )
            existing_genesis = _sql(
                self._connection,
                "SELECT " + ", ".join(_PHASE2_EQUITY_POINT_COLUMNS)
                + " FROM phase2_equity_points "
                "WHERE point_id = ? COLLATE BINARY "
                "OR (window_id = ? COLLATE BINARY AND point_kind = 'START')",
                (str(genesis_record[0]), window_id),
            ).fetchall()
            if inserted_window:
                if existing_genesis:
                    raise IdempotencyConflict(
                        "Phase 2 window genesis conflicts with stored content"
                    )
                try:
                    _sql(
                        self._connection,
                        "INSERT INTO phase2_equity_points("
                        + ", ".join(_PHASE2_EQUITY_POINT_COLUMNS[1:])
                        + ") VALUES ("
                        + ", ".join("?" for _ in genesis_record)
                        + ")",
                        genesis_record,
                    )
                except sqlite3.IntegrityError as error:
                    raise IdempotencyConflict(
                        "Phase 2 window genesis conflicts with stored content"
                    ) from error
            elif (
                len(existing_genesis) != 1
                or tuple(existing_genesis[0][1:]) != genesis_record
            ):
                raise IdempotencyConflict(
                    "Phase 2 window genesis conflicts with stored content"
                )
        source = self.read_phase2_window_source(
            window_id,
            query_cutoff=received_at,
            calendar_resolver=calendar_resolver,
        )
        if source is None:
            raise JournalError("Phase 2 window was not readable after write")
        return source

    def read_phase2_window_source(
        self,
        window_id: str,
        *,
        query_cutoff: datetime,
        calendar_resolver: object,
    ) -> Phase2WindowSource | None:
        """Reissue one exact persisted Phase 2 window at a bounded cutoff."""
        self._ensure_open()
        canonical_window_id = _require_sha256(window_id, "Phase 2 window ID")
        cutoff = _parse_canonical_timestamp(
            _canonical_timestamp(query_cutoff)
        )
        row = _sql(
            self._connection,
            "SELECT " + ", ".join(_PHASE2_WINDOW_COLUMNS)
            + " FROM phase2_windows WHERE window_id = ? COLLATE BINARY",
            (canonical_window_id,),
        ).fetchone()
        if row is None or _parse_canonical_timestamp(str(row[12])) > cutoff:
            return None
        source = self._phase2_window_source_from_row(
            row,
            query_cutoff=cutoff,
            calendar_resolver=calendar_resolver,
        )
        source_identity = id(source)
        owner_reference = ref(self)
        source_total_changes = _journal_source_authority_total_changes(self)
        source_data_version = self._source_authority_data_version()
        source_fingerprint = _phase2_source_fingerprint(source)

        def discard_phase2_window_source(dead: ReferenceType[object]) -> None:
            with _JOURNAL_SOURCE_LOCK:
                current = _PHASE2_SOURCE_AUTHORITIES.get(source_identity)
                if current is not None and current[0] is dead:
                    _PHASE2_SOURCE_AUTHORITIES.pop(source_identity, None)

        with _JOURNAL_SOURCE_LOCK:
            _PHASE2_SOURCE_AUTHORITIES[source_identity] = (
                ref(source, discard_phase2_window_source),
                source_fingerprint,
                owner_reference,
                source_total_changes,
                source_data_version,
            )
        return source

    def authorize_phase2_signal(
        self,
        *,
        window_source: object,
        signal_source: object,
        calendar_resolver: object,
    ) -> Phase2AuthorizationSource:
        """Persist authorization for one exact new post-window PRIMARY."""
        from .options_paper import OptionPaperError, _issue_phase2_authorization
        from .validation import _issue_phase1_promotion_from_journal_source

        self._ensure_open()
        if (
            type(window_source) is not Phase2WindowSource
            or _phase2_registered_source_owner(window_source) is not self
        ):
            raise InvalidJournalValue(
                "Phase 2 window source identity is unverified"
            )
        if (
            type(signal_source) is not Phase1SignalSource
            or _phase1_registered_source_owner(signal_source) is not self
        ):
            raise InvalidJournalValue(
                "Phase 2 signal source identity is unverified"
            )
        authorization_time = max(
            window_source.query_cutoff,
            signal_source.query_cutoff,
        )
        current_window = self.read_phase2_window_source(
            window_source.window_id,
            query_cutoff=authorization_time,
            calendar_resolver=calendar_resolver,
        )
        if (
            current_window is None
            or current_window != window_source
            or current_window.source_digest != window_source.source_digest
        ):
            raise InvalidJournalValue(
                "Phase 2 window source cannot be rederived"
            )
        current_signal = self._read_phase1_signal_source(
            signal_source.signal_id,
            query_cutoff=signal_source.query_cutoff,
        )
        if (
            current_signal != signal_source
            or current_signal.source_digest != signal_source.source_digest
            or not phase2_sources_share_owner(current_window, current_signal)
        ):
            raise InvalidJournalValue(
                "Phase 2 signal source cannot be rederived"
            )
        promotion = _issue_phase1_promotion_from_journal_source(
            current_window.promotion_source,
            calendar_resolver=calendar_resolver,
        )
        try:
            domain_authorization = _issue_phase2_authorization(
                promotion_decision=promotion,
                window_source=current_window,
                signal_source=current_signal,
                issued_at=authorization_time,
            )
        except OptionPaperError as error:
            raise InvalidJournalValue(
                f"Phase 2 signal authorization is invalid: {error}"
            ) from error
        authorization_digest = domain_authorization.source_digest
        authorization_id = _phase2_stable_id(
            "stock-monitor/phase2-authorization/v1",
            current_window.window_id,
            current_signal.signal_id,
            authorization_digest,
        )
        source_references = _phase2_row_references(
            current_window.row_references,
            current_signal.row_references,
        )
        source_digest = _journal_bundle_digest(
            "stock-monitor/phase2-authorization-source/v1",
            source_references,
            {
                "authorization_id": authorization_id,
                "window_id": current_window.window_id,
                "signal_id": current_signal.signal_id,
                "signal_source_digest": current_signal.source_digest,
                "authorization_digest": authorization_digest,
                "authorized_at": _canonical_timestamp(authorization_time),
                "received_at": _canonical_timestamp(authorization_time),
            },
        )
        values_without_hash = (
            authorization_id,
            current_window.window_id,
            current_signal.signal_id,
            current_signal.source_digest,
            authorization_digest,
            _canonical_timestamp(authorization_time),
            _canonical_timestamp(authorization_time),
            source_digest,
        )
        record_sha256 = _phase2_plain_record_digest(
            _PHASE2_AUTHORIZATION_COLUMNS,
            values_without_hash,
        )
        phase2_write_plan = frozenset(
            {
                (
                    "phase2_authorizations",
                    record_sha256,
                    tuple(values_without_hash),
                )
            }
        )
        with self.transaction() as transaction:
            existing = _sql(
                self._connection,
                "SELECT " + ", ".join(_PHASE2_AUTHORIZATION_COLUMNS)
                + " FROM phase2_authorizations "
                "WHERE authorization_id = ? COLLATE BINARY "
                "OR (window_id = ? COLLATE BINARY "
                "AND signal_id = ? COLLATE BINARY)",
                (
                    authorization_id,
                    current_window.window_id,
                    current_signal.signal_id,
                ),
            ).fetchone()
            expected_row = (*values_without_hash, record_sha256)
            if existing is not None:
                if tuple(existing[1:]) != expected_row:
                    raise IdempotencyConflict(
                        "Phase 2 authorization conflicts with stored content"
                    )
            else:
                transaction._mark_dirty()
                try:
                    _sql(
                        self._connection,
                        "INSERT INTO phase2_authorizations("
                        + ", ".join(_PHASE2_AUTHORIZATION_COLUMNS[1:])
                        + ") VALUES ("
                        + ", ".join("?" for _ in expected_row)
                        + ")",
                        expected_row,
                    )
                except sqlite3.IntegrityError as error:
                    raise IdempotencyConflict(
                        "Phase 2 authorization conflicts with stored content"
                    ) from error
        source = self.read_phase2_authorization_source(
            authorization_id,
            query_cutoff=authorization_time,
            calendar_resolver=calendar_resolver,
        )
        if source is None:
            raise JournalError(
                "Phase 2 authorization was not readable after write"
            )
        return source

    def read_phase2_authorization_source(
        self,
        authorization_id: str,
        *,
        query_cutoff: datetime,
        calendar_resolver: object,
    ) -> Phase2AuthorizationSource | None:
        """Reissue one exact persisted post-promotion signal authority."""
        self._ensure_open()
        canonical_authorization_id = _require_sha256(
            authorization_id,
            "Phase 2 authorization ID",
        )
        cutoff = _parse_canonical_timestamp(
            _canonical_timestamp(query_cutoff)
        )
        row = _sql(
            self._connection,
            "SELECT " + ", ".join(_PHASE2_AUTHORIZATION_COLUMNS)
            + " FROM phase2_authorizations "
            "WHERE authorization_id = ? COLLATE BINARY",
            (canonical_authorization_id,),
        ).fetchone()
        if row is None or _parse_canonical_timestamp(str(row[7])) > cutoff:
            return None
        source = self._phase2_authorization_source_from_row(
            row,
            query_cutoff=cutoff,
            calendar_resolver=calendar_resolver,
        )
        source_identity = id(source)
        owner_reference = ref(self)
        source_total_changes = _journal_source_authority_total_changes(self)
        source_data_version = self._source_authority_data_version()
        source_fingerprint = _phase2_source_fingerprint(source)

        def discard_phase2_authorization_source(
            dead: ReferenceType[object],
        ) -> None:
            with _JOURNAL_SOURCE_LOCK:
                current = _PHASE2_SOURCE_AUTHORITIES.get(source_identity)
                if current is not None and current[0] is dead:
                    _PHASE2_SOURCE_AUTHORITIES.pop(source_identity, None)

        with _JOURNAL_SOURCE_LOCK:
            _PHASE2_SOURCE_AUTHORITIES[source_identity] = (
                ref(source, discard_phase2_authorization_source),
                source_fingerprint,
                owner_reference,
                source_total_changes,
                source_data_version,
            )
        return source

    def read_phase2_event_exclusion_source(
        self,
        signal_source: object,
        *,
        calendar_resolver: object,
        query_cutoff: datetime,
    ) -> Phase2EventExclusionSource:
        """Issue the latest persisted ten-session event truth for one signal."""
        from .evidence import EvidenceDecision, ReviewedEvidenceBundle
        from .risk import (
            Phase1SignalEvidenceAuthority,
            RiskBlock,
            SessionCalendarResolver,
            _calendar_digest,
            _issue_phase1_signal_evidence_authority_from_source,
        )

        self._ensure_open()
        if self._transaction_active:
            raise JournalError(
                "Phase 2 event exclusion source requires a post-commit read"
            )
        cutoff = _parse_canonical_timestamp(
            _canonical_timestamp(query_cutoff)
        )
        if not isinstance(calendar_resolver, SessionCalendarResolver) or not (
            calendar_resolver.release_verified
        ):
            raise InvalidJournalValue(
                "Phase 2 event exclusion calendar is unverified"
            )
        try:
            base_calendars = SessionCalendarResolver.calendars.__get__(
                calendar_resolver,
                SessionCalendarResolver,
            )
        except Exception as error:
            raise InvalidJournalValue(
                "Phase 2 event exclusion calendar is unverified"
            ) from error
        if type(base_calendars) is not tuple:
            raise InvalidJournalValue(
                "Phase 2 event exclusion calendar is unverified"
            )
        calendar_digest = _calendar_digest(calendar_resolver)
        if (
            type(signal_source) is not Phase1SignalSource
            or signal_source.calendar_digest != calendar_digest
            or signal_source.query_cutoff < cutoff
            or _phase1_source_owner(signal_source) is not self
        ):
            raise InvalidJournalValue(
                "Phase 2 event exclusion signal identity is unverified"
            )

        initial_data_version = self._source_authority_data_version()
        initial_total_changes = _journal_source_authority_total_changes(self)
        review_rows = _sql(
            self._connection,
            "SELECT id, review_at FROM phase1_signal_evidence_reviews "
            "WHERE signal_id = ? COLLATE BINARY AND recorded_at <= ? "
            "ORDER BY review_at DESC, id DESC",
            (signal_source.signal_id, _canonical_timestamp(cutoff)),
        ).fetchall()
        if not review_rows:
            raise InvalidJournalValue(
                "Phase 2 event exclusion evidence is unavailable"
            )
        if (
            len(review_rows) > 1
            and str(review_rows[0][1]) == str(review_rows[1][1])
        ):
            raise MigrationCorruption(
                "Phase 2 event exclusion latest review is ambiguous"
            )
        reviewed_at = _parse_canonical_timestamp(str(review_rows[0][1]))
        evidence_source = self._read_phase1_signal_evidence_source(
            signal_source.signal_id,
            review_at=reviewed_at,
            query_cutoff=cutoff,
            calendar_resolver=calendar_resolver,
            exact_signal_source=signal_source,
        )
        try:
            evidence_authority = (
                _issue_phase1_signal_evidence_authority_from_source(
                    evidence_source,
                    calendar_resolver=calendar_resolver,
                )
            )
        except RiskBlock as error:
            raise MigrationCorruption(
                "Phase 2 event exclusion evidence cannot be reissued"
            ) from error
        decision = evidence_source.evidence_decision
        reviewed_bundle = evidence_source.reviewed_bundle
        if (
            type(evidence_authority) is not Phase1SignalEvidenceAuthority
            or type(decision) is not EvidenceDecision
            or type(reviewed_bundle) is not ReviewedEvidenceBundle
            or evidence_source.signal_source is not signal_source
            or evidence_authority.signal_source is not signal_source
            or evidence_authority.evidence_decision is not decision
            or evidence_authority.reviewed_bundle is not reviewed_bundle
            or evidence_authority.review_at != reviewed_at
            or evidence_source.review_at != reviewed_at
            or evidence_source.query_cutoff != cutoff
            or evidence_source.calendar_digest != calendar_digest
        ):
            raise MigrationCorruption(
                "Phase 2 event exclusion evidence lineage is inconsistent"
            )

        covered_sessions = tuple(
            calendar_resolver.add_sessions(
                signal_source.publication_session,
                offset,
            )
            for offset in range(10)
        )
        if (
            len(covered_sessions) != 10
            or covered_sessions != tuple(sorted(set(covered_sessions)))
            or covered_sessions[0] != signal_source.publication_session
            or any(
                type(session) is not date
                or not calendar_resolver.is_open(session)
                for session in covered_sessions
            )
        ):
            raise InvalidJournalValue(
                "Phase 2 event exclusion session coverage is incomplete"
            )
        try:
            exact_calendar = SessionCalendarResolver(base_calendars)
            exact_calendar_digest = _calendar_digest(exact_calendar)
            exact_covered_sessions = tuple(
                exact_calendar.add_sessions(
                    signal_source.publication_session,
                    offset,
                )
                for offset in range(10)
            )
        except Exception as error:
            raise InvalidJournalValue(
                "Phase 2 event exclusion session coverage is unverified"
            ) from error
        if (
            exact_calendar_digest != calendar_digest
            or exact_covered_sessions != covered_sessions
            or any(
                not exact_calendar.is_open(session)
                for session in exact_covered_sessions
            )
        ):
            raise InvalidJournalValue(
                "Phase 2 event exclusion session coverage is unverified"
            )
        relevant_event_values = (
            decision.binary_events
            if signal_source.subject_kind == "STOCK"
            else decision.etf_actions
        )
        relevant_coverage = (
            decision.binary_event_coverage
            if signal_source.subject_kind == "STOCK"
            else decision.etf_action_coverage
        )
        if (
            evidence_authority.status == "UNRESOLVED"
            or decision.health != "HEALTHY"
            or decision.ambiguities
            or decision.conflicts
            or relevant_coverage not in {"CONFIRMED_CLEAR", "OVERLAP"}
        ):
            raise InvalidJournalValue(
                "Phase 2 event exclusion evidence is unresolved"
            )
        covered_set = set(covered_sessions)
        if any(
            type(item) is not tuple
            or len(item) != 2
            or type(item[0]) is not date
            or (item[1] is not None and type(item[1]) is not str)
            for item in relevant_event_values
        ):
            raise MigrationCorruption(
                "Phase 2 event exclusion dated events are malformed"
            )
        event_sessions = tuple(
            sorted(
                {
                    item[0]
                    for item in relevant_event_values
                    if item[0] in covered_set
                }
            )
        )
        adverse_records = tuple(
            record for record in reviewed_bundle.records if record.adverse_tags
        )
        expected_event_kind = (
            "BINARY_EVENT"
            if signal_source.subject_kind == "STOCK"
            else "ETF_ACTION"
        )
        if bool(evidence_authority.adverse_tags) != bool(adverse_records):
            raise MigrationCorruption(
                "Phase 2 event exclusion adverse truth is inconsistent"
            )
        if evidence_authority.adverse_tags and (
            not event_sessions
            or any(
                record.event_kind != expected_event_kind
                or record.event_date not in covered_set
                or record.event_date not in event_sessions
                for record in adverse_records
            )
        ):
            raise InvalidJournalValue(
                "Phase 2 adverse evidence lacks a dated event overlap"
            )
        if (relevant_coverage == "OVERLAP") != bool(event_sessions):
            raise MigrationCorruption(
                "Phase 2 event exclusion coverage conflicts with dated events"
            )

        evidence_source_row_ids = tuple(
            evidence_source.source_observation_row_ids
        )
        evidence_source_highwater = evidence_source.source_observation_highwater
        expected_evidence_source_count = (
            evidence_source.expected_source_observation_count
        )
        if (
            not evidence_source_row_ids
            or len(set(evidence_source_row_ids))
            != len(evidence_source_row_ids)
            or any(
                type(row_id) is not int or row_id <= 0
                for row_id in evidence_source_row_ids
            )
            or expected_evidence_source_count != len(evidence_source_row_ids)
            or evidence_source_highwater
            != max(
                evidence_source.registry_source_row_id,
                *evidence_source_row_ids,
            )
        ):
            raise MigrationCorruption(
                "Phase 2 event exclusion evidence cohort is incomplete"
            )
        references = _phase2_row_references(
            signal_source.row_references,
            evidence_source.row_references,
        )
        digest_material = {
            "signal_id": signal_source.signal_id,
            "signal_source_digest": signal_source.source_digest,
            "evidence_id": evidence_source.evidence_id,
            "evidence_source_digest": evidence_source.source_digest,
            "evidence_authority_digest": evidence_authority.source_digest,
            "decision_digest": evidence_source.decision_digest,
            "covered_sessions": [
                session.isoformat() for session in covered_sessions
            ],
            "event_sessions": [session.isoformat() for session in event_sessions],
            "reviewed_at": _canonical_timestamp(reviewed_at),
            "query_cutoff": _canonical_timestamp(cutoff),
            "calendar_digest": calendar_digest,
            "evidence_source_row_ids": list(evidence_source_row_ids),
            "evidence_source_highwater": evidence_source_highwater,
            "expected_evidence_source_count": expected_evidence_source_count,
        }
        source_digest = _journal_bundle_digest(
            "stock-monitor/phase2-event-exclusion-source/v1",
            references,
            digest_material,
        )
        authority_digest = _journal_bundle_digest(
            "stock-monitor/phase2-event-exclusion-authority/v1",
            references,
            {**digest_material, "source_digest": source_digest},
        )
        source = Phase2EventExclusionSource(
            signal_source=signal_source,
            signal_evidence_source=evidence_source,
            covered_sessions=covered_sessions,
            event_sessions=event_sessions,
            reviewed_at=reviewed_at,
            query_cutoff=cutoff,
            calendar_digest=calendar_digest,
            evidence_source_row_ids=evidence_source_row_ids,
            evidence_source_highwater=evidence_source_highwater,
            expected_evidence_source_count=expected_evidence_source_count,
            row_references=references,
            source_digest=source_digest,
            authority_digest=authority_digest,
        )
        before_fingerprint = _phase2_source_fingerprint(source)

        current_data_version = self._source_authority_data_version()
        current_total_changes = _journal_source_authority_total_changes(self)
        if (
            current_data_version != initial_data_version
            or current_total_changes != initial_total_changes
        ):
            raise JournalError(
                "Phase 2 event exclusion source changed during reconstruction"
            )
        signal_candidate = _phase1_source_authority_candidate(signal_source)
        evidence_candidate = _phase1_source_authority_candidate(evidence_source)
        if signal_candidate is None or evidence_candidate is None:
            raise JournalError(
                "Phase 2 event exclusion nested authority is unavailable"
            )
        nested_candidates = (signal_candidate, evidence_candidate)
        if (
            _current_journal_source_authority_owner(nested_candidates)
            is not self
        ):
            raise JournalError(
                "Phase 2 event exclusion nested authority changed"
            )
        source_fingerprint = _phase2_source_fingerprint(source)
        if not _fingerprints_equal(before_fingerprint, source_fingerprint):
            raise JournalError(
                "Phase 2 event exclusion source changed during reconstruction"
            )

        source_identity = id(source)
        owner_reference = ref(self)

        def discard_phase2_event_exclusion_source(
            dead: ReferenceType[object],
        ) -> None:
            with _JOURNAL_SOURCE_LOCK:
                current = _PHASE2_SOURCE_AUTHORITIES.get(source_identity)
                if current is not None and current[0] is dead:
                    _PHASE2_SOURCE_AUTHORITIES.pop(source_identity, None)

        source_reference = ref(
            source,
            discard_phase2_event_exclusion_source,
        )
        with _JOURNAL_SOURCE_LOCK:
            for candidate in nested_candidates:
                registry, nested_source = candidate[0], candidate[1]
                issued = registry.get(id(nested_source))
                if (
                    issued is not candidate[7]
                    or issued[0]() is not nested_source
                    or issued[2]() is not self
                    or issued[3] != initial_total_changes
                    or issued[4] != initial_data_version
                    or issued[1] is not candidate[5]
                ):
                    raise JournalError(
                        "Phase 2 event exclusion nested authority changed"
                    )
            _PHASE2_SOURCE_AUTHORITIES[source_identity] = (
                source_reference,
                source_fingerprint,
                owner_reference,
                initial_total_changes,
                initial_data_version,
            )
        return source

    def read_phase2_portfolio_source(
        self,
        window_source: object,
        *,
        calendar_resolver: object,
        query_cutoff: datetime,
    ) -> Phase2PortfolioSource:
        """Issue the account-wide flat portfolio for one sole window genesis."""
        from .risk import SessionCalendarResolver, _calendar_digest

        self._ensure_open()
        if self._transaction_active:
            raise JournalError(
                "Phase 2 portfolio source requires a post-commit read"
            )
        cutoff = _parse_canonical_timestamp(
            _canonical_timestamp(query_cutoff)
        )
        if not isinstance(calendar_resolver, SessionCalendarResolver) or not (
            calendar_resolver.release_verified
        ):
            raise InvalidJournalValue(
                "Phase 2 portfolio calendar is unverified"
            )
        try:
            base_calendars = SessionCalendarResolver.calendars.__get__(
                calendar_resolver,
                SessionCalendarResolver,
            )
            calendar_digest = _calendar_digest(calendar_resolver)
            exact_calendar = SessionCalendarResolver(base_calendars)
            exact_calendar_digest = _calendar_digest(exact_calendar)
        except Exception as error:
            raise InvalidJournalValue(
                "Phase 2 portfolio calendar is unverified"
            ) from error
        if (
            type(base_calendars) is not tuple
            or calendar_digest != exact_calendar_digest
        ):
            raise InvalidJournalValue(
                "Phase 2 portfolio calendar is unverified"
            )
        if (
            type(window_source) is not Phase2WindowSource
            or window_source.calendar_digest != calendar_digest
            or window_source.received_at > cutoff
            or _phase2_source_owner(window_source) is not self
        ):
            raise InvalidJournalValue(
                "Phase 2 portfolio window identity is unverified"
            )

        initial_data_version = self._source_authority_data_version()
        initial_total_changes = _journal_source_authority_total_changes(self)
        cutoff_text = _canonical_timestamp(cutoff)
        summary_rows = _sql(
            self._connection,
            "SELECT 'phase2_windows', COUNT(*), COALESCE(MAX(id), 0) "
            "FROM phase2_windows WHERE received_at <= ? "
            "UNION ALL "
            "SELECT 'phase2_entries', COUNT(*), COALESCE(MAX(id), 0) "
            "FROM phase2_entries WHERE received_at <= ? "
            "UNION ALL "
            "SELECT 'phase2_marks', COUNT(*), COALESCE(MAX(id), 0) "
            "FROM phase2_marks WHERE received_at <= ? "
            "UNION ALL "
            "SELECT 'phase2_exits', COUNT(*), COALESCE(MAX(id), 0) "
            "FROM phase2_exits WHERE received_at <= ? "
            "UNION ALL "
            "SELECT 'phase2_fee_records', COUNT(*), COALESCE(MAX(id), 0) "
            "FROM phase2_fee_records WHERE recorded_at <= ? "
            "UNION ALL "
            "SELECT 'phase2_equity_points', COUNT(*), COALESCE(MAX(id), 0) "
            "FROM phase2_equity_points WHERE received_at <= ?",
            (cutoff_text,) * 6,
        ).fetchall()
        expected_summary_names = (
            "phase2_windows",
            "phase2_entries",
            "phase2_marks",
            "phase2_exits",
            "phase2_fee_records",
            "phase2_equity_points",
        )
        if (
            len(summary_rows) != len(expected_summary_names)
            or any(
                len(row) != 3
                or type(row[0]) is not str
                or row[0] != expected_name
                or type(row[1]) is not int
                or int(row[1]) < 0
                or type(row[2]) is not int
                or int(row[2]) < 0
                for row, expected_name in zip(
                    summary_rows,
                    expected_summary_names,
                    strict=True,
                )
            )
        ):
            raise MigrationCorruption(
                "Phase 2 portfolio stream summary is malformed"
            )
        stream_summaries = tuple(
            (str(row[0]), int(row[1]), int(row[2]))
            for row in summary_rows
        )
        summary_by_name = {
            name: (count, highwater)
            for name, count, highwater in stream_summaries
        }
        if tuple(count for _name, count, _highwater in stream_summaries) != (
            1,
            0,
            0,
            0,
            0,
            1,
        ):
            raise InvalidJournalValue(
                "Phase 2 portfolio requires a sole genesis ledger"
            )

        window_rows = _sql(
            self._connection,
            "SELECT "
            + ", ".join(_PHASE2_WINDOW_COLUMNS)
            + " FROM phase2_windows WHERE received_at <= ? ORDER BY id",
            (cutoff_text,),
        ).fetchall()
        equity_rows = _sql(
            self._connection,
            "SELECT "
            + ", ".join(_PHASE2_EQUITY_POINT_COLUMNS)
            + " FROM phase2_equity_points WHERE received_at <= ? ORDER BY id",
            (cutoff_text,),
        ).fetchall()
        if len(window_rows) != 1 or len(equity_rows) != 1:
            raise MigrationCorruption(
                "Phase 2 portfolio genesis cohort is incomplete"
            )
        window_row = window_rows[0]
        equity_row = equity_rows[0]
        if (
            len(window_row) != len(_PHASE2_WINDOW_COLUMNS)
            or type(window_row[0]) is not int
            or int(window_row[0]) <= 0
            or str(window_row[-1])
            != _phase2_plain_record_digest(
                _PHASE2_WINDOW_COLUMNS,
                tuple(window_row[1:-1]),
            )
        ):
            raise MigrationCorruption(
                "Phase 2 portfolio window row is malformed"
            )
        try:
            promotion_signal_ids = tuple(json.loads(str(window_row[5])))
            promotion_through_session = date.fromisoformat(str(window_row[6]))
            promotion_cutoff = _parse_canonical_timestamp(str(window_row[7]))
            started_session = date.fromisoformat(str(window_row[10]))
            started_at = _parse_canonical_timestamp(str(window_row[11]))
            received_at = _parse_canonical_timestamp(str(window_row[12]))
        except (TypeError, ValueError, json.JSONDecodeError) as error:
            raise MigrationCorruption(
                "Phase 2 portfolio window fields are malformed"
            ) from error
        window_reference = _journal_row_reference(
            "phase2_windows",
            _PHASE2_WINDOW_COLUMNS,
            window_row,
        )
        if (
            int(window_row[0])
            != summary_by_name["phase2_windows"][1]
            or int(window_row[0]) != window_source.row_id
            or str(window_row[1]) != window_source.window_id
            or str(window_row[2]) != window_source.validation_window_id
            or str(window_row[3]) != window_source.promotion_source.source_digest
            or str(window_row[4]) != window_source.promotion_decision_digest
            or promotion_signal_ids != window_source.promotion_signal_ids
            or promotion_through_session
            != window_source.promotion_source.through_session
            or promotion_cutoff != window_source.promotion_query_cutoff
            or int(window_row[8])
            != window_source.start_action.execution_event_id
            or int(window_row[9]) != window_source.start_action.raw_message_id
            or started_session != window_source.started_session
            or started_at != window_source.started_at
            or received_at != window_source.received_at
            or received_at > cutoff
            or int(window_row[13]) != 5_000_000_000
            or window_source.starting_capital_micros != 5_000_000_000
            or str(window_row[14]) != calendar_digest
            or str(window_row[15]) != window_source.source_digest
        ):
            raise MigrationCorruption(
                "Phase 2 portfolio window identity is inconsistent"
            )

        expected_genesis = _phase2_window_genesis_record(
            window_reference,
            window_id=str(window_row[1]),
            window_source_digest=str(window_row[15]),
            started_session=started_session,
            started_at=started_at,
            received_at=received_at,
        )
        if (
            len(equity_row) != len(_PHASE2_EQUITY_POINT_COLUMNS)
            or type(equity_row[0]) is not int
            or int(equity_row[0]) <= 0
            or int(equity_row[0])
            != summary_by_name["phase2_equity_points"][1]
            or tuple(equity_row[1:]) != expected_genesis
        ):
            raise MigrationCorruption(
                "Phase 2 portfolio START equity is inconsistent"
            )
        genesis_reference = _journal_row_reference(
            "phase2_equity_points",
            _PHASE2_EQUITY_POINT_COLUMNS,
            equity_row,
        )
        ledger_references = (genesis_reference,)
        references = _phase2_row_references(
            (window_reference,),
            ledger_references,
        )
        ledger_terminal_cursor = int(equity_row[0])
        ledger_source_highwater = summary_by_name[
            "phase2_equity_points"
        ][1]
        digest_material = {
            "window_id": str(window_row[1]),
            "window_source_digest": str(window_row[15]),
            "as_of": cutoff_text,
            "query_cutoff": cutoff_text,
            "settled_cash_micros": 5_000_000_000,
            "economic_cash_micros": 5_000_000_000,
            "equity_micros": 5_000_000_000,
            "open_position_source_digest": None,
            "settlement_source_digests": [],
            "unsettled_proceeds_micros": 0,
            "calendar_digest": calendar_digest,
            "ledger_terminal_cursor": ledger_terminal_cursor,
            "ledger_source_highwater": ledger_source_highwater,
            "expected_entry_count": 0,
            "expected_exit_count": 0,
            "expected_fee_count": 0,
            "expected_equity_count": 1,
            "stream_summaries": [
                {
                    "table": name,
                    "count": count,
                    "source_highwater": highwater,
                }
                for name, count, highwater in stream_summaries
            ],
        }
        source_digest = _journal_bundle_digest(
            "stock-monitor/phase2-portfolio-source/v1",
            references,
            digest_material,
        )
        authority_digest = _journal_bundle_digest(
            "stock-monitor/phase2-portfolio-authority/v1",
            references,
            {**digest_material, "source_digest": source_digest},
        )
        source = Phase2PortfolioSource(
            window_id=str(window_row[1]),
            as_of=cutoff,
            query_cutoff=cutoff,
            settled_cash_micros=5_000_000_000,
            economic_cash_micros=5_000_000_000,
            equity_micros=5_000_000_000,
            open_position_source=None,
            settlement_sources=(),
            unsettled_proceeds_micros=0,
            calendar_digest=calendar_digest,
            ledger_row_references=ledger_references,
            ledger_terminal_cursor=ledger_terminal_cursor,
            ledger_source_highwater=ledger_source_highwater,
            expected_entry_count=0,
            expected_exit_count=0,
            expected_fee_count=0,
            expected_equity_count=1,
            row_references=references,
            source_digest=source_digest,
            authority_digest=authority_digest,
        )
        before_fingerprint = _phase2_source_fingerprint(source)

        current_data_version = self._source_authority_data_version()
        current_total_changes = _journal_source_authority_total_changes(self)
        if (
            current_data_version != initial_data_version
            or current_total_changes != initial_total_changes
        ):
            raise JournalError(
                "Phase 2 portfolio source changed during reconstruction"
            )
        window_candidate = _phase2_source_authority_candidate(window_source)
        if window_candidate is None or (
            _current_journal_source_authority_owner((window_candidate,))
            is not self
        ):
            raise JournalError(
                "Phase 2 portfolio window authority changed"
            )
        source_fingerprint = _phase2_source_fingerprint(source)
        if not _fingerprints_equal(before_fingerprint, source_fingerprint):
            raise JournalError(
                "Phase 2 portfolio source changed during reconstruction"
            )

        source_identity = id(source)
        owner_reference = ref(self)

        def discard_phase2_portfolio_source(
            dead: ReferenceType[object],
        ) -> None:
            with _JOURNAL_SOURCE_LOCK:
                current = _PHASE2_SOURCE_AUTHORITIES.get(source_identity)
                if current is not None and current[0] is dead:
                    _PHASE2_SOURCE_AUTHORITIES.pop(source_identity, None)
                binding = _PHASE2_PORTFOLIO_WINDOW_AUTHORITIES.get(
                    source_identity
                )
                if (
                    binding is not None
                    and binding.portfolio_reference is dead
                ):
                    _PHASE2_PORTFOLIO_WINDOW_AUTHORITIES.pop(
                        source_identity,
                        None,
                    )

        source_reference = ref(source, discard_phase2_portfolio_source)
        source_issued = (
            source_reference,
            source_fingerprint,
            owner_reference,
            initial_total_changes,
            initial_data_version,
        )
        window_binding = _Phase2PortfolioWindowAuthority(
            portfolio_reference=source_reference,
            window_source=window_source,
            portfolio_issued=source_issued,
            window_issued=window_candidate[7],
        )
        with _JOURNAL_SOURCE_LOCK:
            registry, nested_source = (
                window_candidate[0],
                window_candidate[1],
            )
            issued = registry.get(id(nested_source))
            if (
                issued is not window_candidate[7]
                or issued[0]() is not nested_source
                or issued[2]() is not self
                or issued[3] != initial_total_changes
                or issued[4] != initial_data_version
                or issued[1] is not window_candidate[5]
            ):
                raise JournalError(
                    "Phase 2 portfolio window authority changed"
                )
            _PHASE2_SOURCE_AUTHORITIES[source_identity] = source_issued
            _PHASE2_PORTFOLIO_WINDOW_AUTHORITIES[
                source_identity
            ] = window_binding
        return source

    def archive_phase2_fee_schedule(
        self,
        schedule: object,
        *,
        archived_at: datetime,
    ) -> Phase2FeeScheduleSource:
        """Archive and issue one exact reviewed Phase 2 fee schedule."""
        with self.transaction() as transaction:
            transaction.archive_phase2_fee_schedule(
                schedule,
                archived_at=archived_at,
            )
        source = self.read_phase2_fee_schedule_source(
            getattr(schedule, "schedule_id", ""),
            query_cutoff=archived_at,
        )
        if source is None:
            raise JournalError("Phase 2 fee schedule archive was not readable")
        return source

    def read_phase2_fee_schedule_source(
        self,
        schedule_id: str,
        *,
        query_cutoff: datetime,
    ) -> Phase2FeeScheduleSource | None:
        """Reissue one archived schedule no later than the exact cutoff."""
        self._ensure_open()
        if not isinstance(schedule_id, str) or not schedule_id:
            raise InvalidJournalValue("Phase 2 fee schedule ID is invalid")
        cutoff = _canonical_timestamp(query_cutoff)
        row = _sql(
            self._connection,
            "SELECT "
            + ", ".join(_PHASE2_FEE_SCHEDULE_COLUMNS)
            + " FROM phase2_fee_schedules "
            "WHERE schedule_id = ? COLLATE BINARY AND archived_at <= ?",
            (schedule_id, cutoff),
        ).fetchone()
        if row is None:
            return None
        source = self._phase2_fee_schedule_source_from_row(row)
        source_identity = id(source)
        owner_reference = ref(self)
        source_total_changes = _journal_source_authority_total_changes(self)
        source_data_version = self._source_authority_data_version()
        source_fingerprint = _phase2_source_fingerprint(source)

        def discard_phase2_fee_source(dead: ReferenceType[object]) -> None:
            with _JOURNAL_SOURCE_LOCK:
                current = _PHASE2_SOURCE_AUTHORITIES.get(source_identity)
                if current is not None and current[0] is dead:
                    _PHASE2_SOURCE_AUTHORITIES.pop(source_identity, None)

        with _JOURNAL_SOURCE_LOCK:
            _PHASE2_SOURCE_AUTHORITIES[source_identity] = (
                ref(source, discard_phase2_fee_source),
                source_fingerprint,
                owner_reference,
                source_total_changes,
                source_data_version,
            )
        return source

    def archive_historical_replay_source(
        self,
        *,
        run_id: str,
        session_dates: Sequence[date],
        query_cutoff: datetime,
        calendar_resolver: object,
        policy: object,
    ) -> HistoricalReplaySource:
        """Seal one exact point-in-time replay snapshot and issue its source."""
        self._ensure_open()
        canonical_run_id = _require_sha256(run_id, "historical replay run ID")
        (
            canonical_sessions,
            normalized_cutoff,
            calendar_digest,
            policy_digest,
            report_cutoffs,
        ) = self._historical_replay_request_configuration(
            session_dates=session_dates,
            query_cutoff=query_cutoff,
            calendar_resolver=calendar_resolver,
            policy=policy,
        )
        existing = _sql(
            self._connection,
            "SELECT 1 FROM historical_replay_runs "
            "WHERE replay_run_id = ? COLLATE BINARY",
            (canonical_run_id,),
        ).fetchone()
        if existing is not None:
            if not self._historical_replay_request_matches(
                run_id=canonical_run_id,
                session_dates=canonical_sessions,
                query_cutoff=normalized_cutoff,
                calendar_digest=calendar_digest,
                policy_digest=policy_digest,
                report_cutoffs=report_cutoffs,
            ):
                raise IdempotencyConflict(
                    "historical replay run identity conflicts with stored content"
                )
            source = self.read_historical_replay_source(
                canonical_run_id,
                query_cutoff=normalized_cutoff,
                calendar_resolver=calendar_resolver,
                policy=policy,
            )
            if source is None:
                raise MigrationCorruption(
                    "historical replay retry could not read its sealed source"
                )
            return source

        date_plans = tuple(
            self._prepare_historical_replay_date(
                session_date=session_date,
                report_cutoff=report_cutoff,
                calendar_resolver=calendar_resolver,
                policy=policy,
            )
            for session_date, report_cutoff in zip(
                canonical_sessions, report_cutoffs, strict=True
            )
        )
        recorded_at = _parse_canonical_timestamp(_canonical_timestamp(_utc_now()))
        if recorded_at < normalized_cutoff:
            raise InvalidJournalValue(
                "historical replay cannot be recorded before its cutoff"
            )
        with self.transaction() as transaction:
            transaction._mark_dirty()
            self._archive_historical_replay_source(
                run_id=canonical_run_id,
                session_dates=canonical_sessions,
                query_cutoff=normalized_cutoff,
                calendar_digest=calendar_digest,
                policy_digest=policy_digest,
                date_plans=date_plans,
                recorded_at=recorded_at,
            )
        source = self.read_historical_replay_source(
            canonical_run_id,
            query_cutoff=normalized_cutoff,
            calendar_resolver=calendar_resolver,
            policy=policy,
        )
        if source is None:
            raise JournalError("historical replay archive was not readable")
        return source

    def read_historical_replay_source(
        self,
        run_id: str,
        *,
        query_cutoff: datetime,
        calendar_resolver: object,
        policy: object,
    ) -> HistoricalReplaySource | None:
        """Reissue one exact sealed historical replay source from storage."""
        self._ensure_open()
        canonical_run_id = _require_sha256(run_id, "historical replay run ID")
        normalized_cutoff = _parse_canonical_timestamp(
            _canonical_timestamp(query_cutoff)
        )
        row = _sql(
            self._connection,
            "SELECT "
            + ", ".join(_HISTORICAL_REPLAY_RUN_COLUMNS)
            + " FROM historical_replay_runs "
            "WHERE replay_run_id = ? COLLATE BINARY",
            (canonical_run_id,),
        ).fetchone()
        if row is None:
            return None
        source = self._historical_replay_source_from_rows(
            row,
            query_cutoff=normalized_cutoff,
            calendar_resolver=calendar_resolver,
            policy=policy,
        )
        issued_sources: tuple[object, ...] = (
            *(
                evidence_source
                for date_source in source.date_sources
                for evidence_source in date_source.evidence_sources
            ),
            *source.date_sources,
            source,
        )
        owner_reference = ref(self)
        source_total_changes = _journal_source_authority_total_changes(self)
        source_data_version = self._source_authority_data_version()

        def discard_phase2_replay_source(
            source_identity: int,
        ):
            def discard(dead: ReferenceType[object]) -> None:
                with _JOURNAL_SOURCE_LOCK:
                    current = _PHASE2_SOURCE_AUTHORITIES.get(source_identity)
                    if current is not None and current[0] is dead:
                        _PHASE2_SOURCE_AUTHORITIES.pop(source_identity, None)

            return discard

        with _JOURNAL_SOURCE_LOCK:
            for issued_source in issued_sources:
                source_identity = id(issued_source)
                _PHASE2_SOURCE_AUTHORITIES[source_identity] = (
                    ref(
                        issued_source,
                        discard_phase2_replay_source(source_identity),
                    ),
                    _phase2_source_fingerprint(issued_source),
                    owner_reference,
                    source_total_changes,
                    source_data_version,
                )
        for date_source in source.date_sources:
            self._historical_replay_date_contexts[id(date_source)] = (
                ref(date_source),
                calendar_resolver,
                policy,
            )
        from .replay import _register_historical_replay_source

        _register_historical_replay_source(source)
        return source

